CREATE OR REPLACE FUNCTION public.accept_membership_terms(p_line_user_id text, p_terms_id uuid, p_version text, p_accepted boolean, p_birthday date DEFAULT NULL::date, p_phone text DEFAULT NULL::text, p_surname text DEFAULT NULL::text, p_salutation text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_member public.members%rowtype; v_terms public.membership_terms%rowtype; v_join boolean;
begin
 if p_accepted is distinct from true then raise exception 'TERMS_CONSENT_REQUIRED'; end if;
 select * into v_member from public.members where line_user_id=p_line_user_id for update;
 if not found or v_member.status <> 'active' then raise exception 'MEMBER_NOT_FOUND'; end if;
 select * into v_terms from public.membership_terms where status='active' for share;
 if not found then raise exception 'TERMS_UNAVAILABLE'; end if;
 if v_terms.id is distinct from p_terms_id or v_terms.version is distinct from p_version or not v_terms.required or v_terms.effective_at > now() then
   raise exception 'TERMS_VERSION_STALE';
 end if;
 v_join := v_member.membership_status <> 'active';
 if v_join and (p_birthday is null or p_birthday > current_date or p_birthday < date '1900-01-01'
     or p_phone !~ '^\+[1-9][0-9]{7,14}$'
     or p_phone ~ '([0-9])\1{6,}'
     or (p_phone like '+886%' and p_phone !~ '^\+886(9[0-9]{8}|[2-8][0-9]{7,8})$')
     or length(btrim(coalesce(p_surname,''))) not between 1 and 40
     or p_salutation not in ('mr','ms')) then raise exception 'INVALID_PROFILE'; end if;
 insert into public.membership_consents(member_id,terms_id) values(v_member.id,v_terms.id) on conflict (member_id,terms_id) do nothing;
 if v_join then
   update public.members set birthday=p_birthday,phone=p_phone,surname=btrim(p_surname),salutation=p_salutation,
      membership_status='active',joined_at=coalesce(joined_at,now()),updated_at=now() where id=v_member.id;
 end if;
 insert into public.audit_logs(audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail)
 values('AUD-'||replace(gen_random_uuid()::text,'-',''),p_line_user_id,'member',
        case when v_join then 'MEMBERSHIP_JOIN_CONSENT' else 'MEMBERSHIP_TERMS_RECONSENT' end,
        'member',v_member.id::text,'success',jsonb_build_object('termsId',v_terms.id,'version',v_terms.version));
 return v_join;
end $function$
CREATE OR REPLACE FUNCTION public.accept_membership_terms_api(p_payload jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_line_user_id text;
  v_terms_id uuid;
  v_version text;
  v_accepted boolean;
  v_birthday date;
  v_phone text;
  v_surname text;
  v_salutation text;
begin
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'INVALID_PROFILE';
  end if;

  v_line_user_id := nullif(btrim(p_payload->>'lineUserId'), '');
  v_version := nullif(btrim(p_payload->>'termsVersion'), '');
  v_accepted := coalesce((p_payload->>'accepted')::boolean, false);

  begin
    v_terms_id := nullif(p_payload->>'termsId', '')::uuid;
  exception when invalid_text_representation then
    raise exception 'TERMS_VERSION_STALE';
  end;

  if v_line_user_id is null or v_terms_id is null or v_version is null then
    raise exception 'TERMS_VERSION_STALE';
  end if;

  if nullif(p_payload->>'birthday', '') is not null then
    begin
      v_birthday := (p_payload->>'birthday')::date;
    exception when others then
      raise exception 'INVALID_PROFILE';
    end;
  end if;

  v_phone := nullif(p_payload->>'phone', '');
  v_surname := nullif(btrim(p_payload->>'surname'), '');
  v_salutation := nullif(lower(btrim(p_payload->>'salutation')), '');

  return public.accept_membership_terms(
    v_line_user_id,
    v_terms_id,
    v_version,
    v_accepted,
    v_birthday,
    v_phone,
    v_surname,
    v_salutation
  );
end;
$function$
CREATE OR REPLACE FUNCTION public.activate_membership_terms(p_actor text, p_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_terms public.membership_terms%rowtype; v_previous jsonb;
begin
 if not public.membership_terms_admin_ok(p_actor) then raise exception 'ADMIN_REQUIRED'; end if;
 -- Serializes competing activations and registration against the terms row.
 lock table public.membership_terms in share row exclusive mode;
 select * into v_terms from public.membership_terms where id=p_id and status='draft' for update;
 if not found then raise exception 'TERMS_IMMUTABLE'; end if;
 if not v_terms.required or v_terms.effective_at > now() then raise exception 'TERMS_NOT_EFFECTIVE'; end if;
 select to_jsonb(t) into v_previous from public.membership_terms t where status='active';
 update public.membership_terms set status='archived',updated_by=p_actor,updated_at=now() where status='active';
 update public.membership_terms set status='active',activated_at=now(),updated_by=p_actor,updated_at=now() where id=p_id;
 insert into public.audit_logs(audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail)
 values('AUD-'||replace(gen_random_uuid()::text,'-',''),p_actor,'admin','MEMBERSHIP_TERMS_ACTIVATE','membership_terms',p_id::text,'success',
        jsonb_build_object('before',v_previous,'after',(select to_jsonb(t) from public.membership_terms t where id=p_id)));
 return p_id;
end $function$
CREATE OR REPLACE FUNCTION public.admin_acquire_test_execution_lease(p_actor text, p_ttl_minutes integer DEFAULT 60)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor text := left(btrim(coalesce(p_actor,'')), 180);
  v_ttl integer := greatest(5, least(120, coalesce(p_ttl_minutes, 60)));
  v_id uuid;
begin
  if v_actor = '' then
    raise exception 'TEST_EXECUTION_ACTOR_REQUIRED';
  end if;

  perform pg_advisory_xact_lock(2026092001);
  perform pg_advisory_xact_lock(2026092202);

  delete from public.test_execution_leases
   where expires_at <= clock_timestamp();

  insert into public.test_execution_leases(lease_type, actor_line_user_id, expires_at)
  values ('full_e2e', v_actor, clock_timestamp() + make_interval(mins => v_ttl))
  returning id into v_id;

  return v_id;
end
$function$
CREATE OR REPLACE FUNCTION public.admin_advance_e2e_evolution(p_seed text, p_complexity_level integer, p_root_run_id text)
 RETURNS e2e_evolution_state
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row public.e2e_evolution_state;
  v_level integer := greatest(1, least(8, coalesce(p_complexity_level, 1)));
  v_seed text := left(coalesce(p_seed, ''), 160);
  v_root_run_id text := left(coalesce(p_root_run_id, ''), 80);
begin
  if v_root_run_id = '' then
    raise exception 'root run id is required';
  end if;

  insert into public.e2e_evolution_state (
    id, run_count, last_complexity_level, last_seed, last_root_run_id, updated_at
  )
  values (true, 1, v_level, v_seed, v_root_run_id, now())
  on conflict (id) do update
  set
    run_count = case
      when public.e2e_evolution_state.last_root_run_id = excluded.last_root_run_id
        then public.e2e_evolution_state.run_count
      else public.e2e_evolution_state.run_count + 1
    end,
    last_complexity_level = case
      when public.e2e_evolution_state.last_root_run_id = excluded.last_root_run_id
        then public.e2e_evolution_state.last_complexity_level
      else excluded.last_complexity_level
    end,
    last_seed = case
      when public.e2e_evolution_state.last_root_run_id = excluded.last_root_run_id
        then public.e2e_evolution_state.last_seed
      else excluded.last_seed
    end,
    last_root_run_id = excluded.last_root_run_id,
    updated_at = case
      when public.e2e_evolution_state.last_root_run_id = excluded.last_root_run_id
        then public.e2e_evolution_state.updated_at
      else now()
    end
  returning * into v_row;

  return v_row;
end;
$function$
CREATE OR REPLACE FUNCTION public.admin_booking_notification_summary(p_admin_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_last_read bigint := 0;
  v_latest bigint := 0;
  v_unread integer := 0;
  v_unread_bookings integer := 0;
  v_unread_cancellations integer := 0;
begin
  select coalesce(r.last_read_notification_id, 0)
    into v_last_read
  from public.admin_booking_notification_reads r
  where r.admin_line_user_id = p_admin_line_user_id;

  v_last_read := coalesce(v_last_read, 0);

  select
    coalesce(max(n.id), 0),
    count(*) filter (where n.id > v_last_read)::integer,
    count(*) filter (where n.id > v_last_read and n.kind = 'booking_created')::integer,
    count(*) filter (where n.id > v_last_read and n.kind = 'cancellation_requested')::integer
  into v_latest, v_unread, v_unread_bookings, v_unread_cancellations
  from public.admin_booking_notifications n;

  return jsonb_build_object(
    'unreadCount', coalesce(v_unread, 0),
    'unreadBookingCount', coalesce(v_unread_bookings, 0),
    'unreadCancellationCount', coalesce(v_unread_cancellations, 0),
    'latestNotificationId', coalesce(v_latest, 0),
    'lastReadNotificationId', v_last_read
  );
end;
$function$
CREATE OR REPLACE FUNCTION public.admin_confirm_booking_receipt_request(p_booking_id uuid, p_expected_booking_updated_at timestamp with time zone, p_actor_line_user_id text, p_admin_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_booking public.bookings%rowtype;
  v_receipt public.booking_receipts%rowtype;
  v_settlement jsonb;
begin
  select * into v_booking
  from public.bookings
  where id=p_booking_id
  for update;
  if not found then raise exception 'BOOKING_NOT_FOUND'; end if;

  if v_booking.status='completed' then
    select * into v_receipt
    from public.booking_receipts
    where booking_id=p_booking_id and status='bound'
    order by bound_at desc nulls last, created_at desc
    limit 1;
    select jsonb_build_object(
      'bookingId',s.booking_id,
      'serviceMinutes',s.service_minutes,
      'rewards',s.reward_details
    ) into v_settlement
    from public.booking_completion_settlements s
    where s.booking_id=p_booking_id;
    return jsonb_build_object(
      'receiptId',coalesce(v_receipt.receipt_id,''),
      'bookingId',p_booking_id,
      'status','bound',
      'settlement',coalesce(v_settlement,'{}'::jsonb),
      'alreadyApplied',true
    );
  end if;

  if v_booking.status<>'confirmed' then raise exception 'INVALID_BOOKING_TRANSITION'; end if;
  if v_booking.cancellation_requested_at is not null and v_booking.cancellation_reviewed_at is null then
    raise exception 'BOOKING_CANCELLATION_PENDING';
  end if;
  if p_expected_booking_updated_at is null or v_booking.updated_at<>p_expected_booking_updated_at then
    raise exception 'BOOKING_CONFLICT';
  end if;

  select * into v_receipt
  from public.booking_receipts
  where booking_id=p_booking_id and status='awaiting_review'
  order by created_at desc
  limit 1
  for update;
  if not found then raise exception 'RECEIPT_AWAITING_REVIEW_REQUIRED'; end if;

  v_settlement:=public.complete_booking_with_benefits_request(
    p_booking_id,
    p_expected_booking_updated_at,
    p_actor_line_user_id,
    left(coalesce(p_admin_note,''),500)
  );

  update public.booking_receipts
  set status='bound',
      bound_at=now(),
      failure_reason='',
      updated_at=now()
  where id=v_receipt.id;

  insert into public.audit_logs(
    audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail
  ) values(
    public.new_public_id('AUD'),p_actor_line_user_id,'admin','admin.booking.receipt.confirm',
    'booking',p_booking_id::text,'success',
    jsonb_build_object(
      'receiptId',v_receipt.receipt_id,
      'objectPath',v_receipt.object_path,
      'previousReceiptStatus','awaiting_review',
      'nextReceiptStatus','bound'
    )
  );

  return jsonb_build_object(
    'receiptId',v_receipt.receipt_id,
    'bookingId',p_booking_id,
    'status','bound',
    'settlement',v_settlement,
    'alreadyApplied',false
  );
end;
$function$
CREATE OR REPLACE FUNCTION public.admin_delete_test_accounts(p_member_ids uuid[])
 RETURNS TABLE(deleted_account_count integer, total_test_accounts integer)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_requested_count integer := coalesce(cardinality(p_member_ids), 0);
  v_distinct_count integer := 0;
  v_matched_count integer := 0;
  v_deleted_count integer := 0;
  v_remaining_count integer := 0;
  v_line_user_ids text[] := array[]::text[];
  v_member_codes text[] := array[]::text[];
  v_member_id_texts text[] := array[]::text[];
  v_booking_ids uuid[] := array[]::uuid[];
  v_booking_id_texts text[] := array[]::text[];
begin
  if v_requested_count < 1 or v_requested_count > 200 then
    raise exception 'INVALID_TEST_ACCOUNT_DELETE_COUNT';
  end if;

  select count(distinct member_id)::integer
    into v_distinct_count
    from unnest(p_member_ids) as requested(member_id);

  if v_distinct_count <> v_requested_count then
    raise exception 'DUPLICATE_TEST_ACCOUNT_ID';
  end if;

  perform pg_advisory_xact_lock(2026092001);

  perform id
    from public.members
   where id = any(p_member_ids)
   for update;

  select
    count(*)::integer,
    coalesce(array_agg(line_user_id order by id) filter (where line_user_id is not null), array[]::text[]),
    coalesce(array_agg(member_code order by id) filter (where member_code is not null), array[]::text[]),
    coalesce(array_agg(id::text order by id), array[]::text[])
  into
    v_matched_count,
    v_line_user_ids,
    v_member_codes,
    v_member_id_texts
  from public.members
  where id = any(p_member_ids)
    and is_test_account = true;

  if v_matched_count <> v_requested_count then
    raise exception 'INVALID_TEST_ACCOUNT_SELECTION';
  end if;

  select
    coalesce(array_agg(id order by id), array[]::uuid[]),
    coalesce(array_agg(id::text order by id), array[]::text[])
  into
    v_booking_ids,
    v_booking_id_texts
  from public.bookings
  where member_id = any(p_member_ids);

  if exists (
    select 1
      from public.point_transfers t
      join public.members sender on sender.id = t.sender_member_id
      join public.members receiver on receiver.id = t.receiver_member_id
     where (t.sender_member_id = any(p_member_ids) or t.receiver_member_id = any(p_member_ids))
       and (sender.is_test_account is not true or receiver.is_test_account is not true)
  ) then
    raise exception 'TEST_DATA_CROSS_BOUNDARY_POINT_TRANSFER';
  end if;

  if exists (
    select 1
      from public.member_referrals r
      join public.members inviter on inviter.id = r.inviter_member_id
      join public.members invitee on invitee.id = r.invitee_member_id
     where (r.inviter_member_id = any(p_member_ids) or r.invitee_member_id = any(p_member_ids))
       and (inviter.is_test_account is not true or invitee.is_test_account is not true)
  ) then
    raise exception 'TEST_DATA_CROSS_BOUNDARY_REFERRAL';
  end if;

  delete from public.api_rate_limits
   where principal_hash = any (
     select encode(extensions.digest(line_user_id, 'sha256'), 'hex')
     from unnest(v_line_user_ids) as ids(line_user_id)
   );

  delete from public.idempotency_results
   where actor_line_user_id = any(v_line_user_ids)
      or exists (
        select 1
        from unnest(v_member_id_texts || v_member_codes || v_booking_id_texts || v_line_user_ids) as ids(value)
        where result::text like '%' || value || '%'
      );

  delete from public.booking_audit_events
   where actor_line_user_id = any(v_line_user_ids)
      or target_id = any(v_member_id_texts)
      or target_id = any(v_member_codes)
      or target_id = any(v_booking_id_texts)
      or exists (
        select 1
        from unnest(v_member_id_texts || v_member_codes || v_booking_id_texts || v_line_user_ids) as ids(value)
        where metadata::text like '%' || value || '%'
      );

  delete from public.audit_logs
   where actor_line_user_id = any(v_line_user_ids)
      or target_id = any(v_member_id_texts)
      or target_id = any(v_member_codes)
      or target_id = any(v_booking_id_texts)
      or exists (
        select 1
        from unnest(v_member_id_texts || v_member_codes || v_booking_id_texts || v_line_user_ids) as ids(value)
        where detail::text like '%' || value || '%'
      );

  delete from booking_notifications.outbox
   where booking_id = any(v_booking_ids);

  delete from public.booking_completion_settlements
   where member_id = any(p_member_ids)
      or booking_id = any(v_booking_ids);

  delete from public.member_referrals
   where inviter_member_id = any(p_member_ids)
      or invitee_member_id = any(p_member_ids);

  delete from public.point_transfers
   where sender_member_id = any(p_member_ids)
      or receiver_member_id = any(p_member_ids);

  delete from public.birthday_benefit_grants
   where member_id = any(p_member_ids);

  delete from public.event_ticket_claims
   where member_id = any(p_member_ids);

  delete from public.scheduled_grant_messages
   where member_id = any(p_member_ids)
      or line_user_id = any(v_line_user_ids);

  delete from public.point_tickets
   where member_id = any(p_member_ids);

  delete from public.point_entries
   where member_id = any(p_member_ids);

  delete from public.point_balances
   where member_id = any(p_member_ids);

  delete from public.service_time_entries
   where member_id = any(p_member_ids);

  delete from public.fixed_ticket_grants
   where member_id = any(p_member_ids);

  delete from public.bookings
   where member_id = any(p_member_ids);

  delete from public.test_login_sessions
   where member_id = any(p_member_ids);

  delete from public.members
   where id = any(p_member_ids)
     and is_test_account = true;

  get diagnostics v_deleted_count = row_count;

  if v_deleted_count <> v_requested_count then
    raise exception 'TEST_ACCOUNT_DELETE_MISMATCH';
  end if;

  select count(*)::integer
    into v_remaining_count
  from public.members
  where is_test_account = true;

  if v_remaining_count = 0 then
    perform setval('public.test_member_sequence', 1, false);
  end if;

  return query
  select v_deleted_count, v_remaining_count;
end;
$function$
CREATE OR REPLACE FUNCTION public.admin_e2e_automation_health()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with expected(name, grace) as (
    values ('issue-fixed-tickets', interval '36 hours'),
           ('dispatch-scheduled-grant-messages', interval '15 minutes'),
           ('dispatch-booking-line-notifications', interval '5 minutes'),
           ('sync-booking-day-before-reminders', interval '20 minutes'),
           ('prune-e2e-failure-artifacts', interval '36 hours')
  ), jobs as (
    select e.name,j.active,j.schedule,r.status,r.start_time,r.end_time,
      coalesce(r.start_time >= now() - e.grace,false) as fresh
    from expected e left join cron.job j on j.jobname=e.name
    left join lateral (
      select status,start_time,end_time from cron.job_run_details
      where jobid=j.jobid order by start_time desc,runid desc limit 1
    ) r on true
  )
  select jsonb_build_object('checkedAt',now(),'jobs',coalesce(jsonb_agg(jsonb_build_object(
    'name',name,'active',coalesce(active,false),'schedule',schedule,
    'lastStatus',status,'lastStartedAt',start_time,'lastEndedAt',end_time,'fresh',fresh
  ) order by name),'[]'::jsonb)) from jobs;
$function$
