CREATE OR REPLACE FUNCTION public.claim_booking_notifications(p_limit integer DEFAULT 20)
 RETURNS SETOF booking_notifications.outbox
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not coalesce((select enabled from booking_notifications.config where id), false) then
    return;
  end if;

  update booking_notifications.outbox
  set status = 'failed',
      last_error = 'Retry limit reached'
  where status in ('pending','sending')
    and next_attempt_at <= now()
    and (attempt_count >= 5 or first_attempt_at < now() - interval '12 hours');

  update booking_notifications.outbox q
  set status = 'skipped',
      last_error = 'Administrator no longer active'
  where q.status in ('pending','sending')
    and q.channel = 'admin'
    and q.next_attempt_at <= now()
    and not exists (
      select 1
      from public.admins a
      where a.line_user_id = q.recipient
        and a.status = 'active'
        and a.role = 'admin'
    );

  update booking_notifications.outbox q
  set status = 'skipped',
      last_error = 'Superseded by current booking lifecycle state'
  from public.bookings b
  where q.booking_id = b.id
    and q.status in ('pending','sending')
    and q.next_attempt_at <= now()
    and (
      (b.status = 'cancelled' and q.event_key not like (b.id::text || ':cancelled:%'))
      or (b.status = 'completed' and q.event_key not like (b.id::text || ':completed:%'))
      or (b.status = 'rejected' and q.event_key not like (b.id::text || ':rejected:%'))
      or (
        b.status in ('pending','confirmed')
        and b.cancellation_requested_at is not null
        and b.cancellation_reviewed_at is null
        and q.event_key not like (b.id::text || ':cancellation_requested:%')
      )
      or (
        b.status in ('pending','confirmed')
        and b.cancellation_decision = 'rejected'
        and b.cancellation_reviewed_at is not null
        and q.event_key like (b.id::text || ':cancellation_requested:%')
      )
    );

  return query
  with due as (
    select id
    from booking_notifications.outbox
    where status in ('pending','sending')
      and next_attempt_at <= now()
    order by next_attempt_at, created_at
    limit greatest(1, least(p_limit, 20))
    for update skip locked
  )
  update booking_notifications.outbox q
  set status = 'sending',
      attempt_count = q.attempt_count + 1,
      first_attempt_at = coalesce(q.first_attempt_at, now()),
      next_attempt_at = now() + interval '2 minutes'
  from due
  where q.id = due.id
  returning q.*;
end;
$function$
CREATE OR REPLACE FUNCTION public.claim_due_grant_messages(p_limit integer DEFAULT 20)
 RETURNS SETOF scheduled_grant_messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.scheduled_grant_messages
  set status='pending',
      scheduled_for=now(),
      last_error=case when last_error='' then 'dispatcher_timeout' else last_error end,
      updated_at=now()
  where status='sending'
    and updated_at < now() - interval '10 minutes'
    and attempt_count < 3;

  update public.scheduled_grant_messages
  set status='failed',
      last_error=case when last_error='' then 'max_attempts_reached' else last_error end,
      updated_at=now()
  where status='sending'
    and updated_at < now() - interval '10 minutes'
    and attempt_count >= 3;

  return query
  with candidates as (
    select id
    from public.scheduled_grant_messages
    where status='pending'
      and scheduled_for <= now()
    order by scheduled_for, created_at
    for update skip locked
    limit greatest(1,least(coalesce(p_limit,20),50))
  )
  update public.scheduled_grant_messages s
  set status='sending',
      attempt_count=s.attempt_count+1,
      updated_at=now()
  from candidates c
  where s.id=c.id
  returning s.*;
end;
$function$
CREATE OR REPLACE FUNCTION public.claim_event_ticket(p_line_user_id text, p_event_ticket_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_member public.members%rowtype;
  v_event public.event_tickets%rowtype;
  v_tier text;
  v_claim_id text;
  v_today date;
  v_count integer;
begin
  select * into v_member from public.members
    where line_user_id=p_line_user_id and membership_status='active' and status='active';
  if not found then raise exception 'MEMBERSHIP_REQUIRED'; end if;

  select * into v_event from public.event_tickets
    where event_ticket_id=p_event_ticket_id for update;
  if not found then raise exception 'EVENT_TICKET_NOT_AVAILABLE'; end if;
  if v_event.fixed_ticket_template_id is not null then raise exception 'FIXED_TICKET_AUTO_ONLY'; end if;
  if v_event.ticket_type = 'referral' then raise exception 'REFERRAL_TICKET_AUTO_ONLY'; end if;
  if v_event.ticket_type = 'membership_join' then raise exception 'MEMBERSHIP_JOIN_TICKET_AUTO_ONLY'; end if;

  select claim_id into v_claim_id from public.event_ticket_claims
    where event_ticket_id=v_event.id and member_id=v_member.id;
  if found then return jsonb_build_object('claimId',v_claim_id,'alreadyClaimed',true); end if;

  if v_event.deleted_at is not null or v_event.status <> 'active' then raise exception 'EVENT_TICKET_NOT_AVAILABLE'; end if;
  v_today := (clock_timestamp() at time zone 'Asia/Taipei')::date;
  if v_event.starts_on is not null and v_today < v_event.starts_on then raise exception 'EVENT_NOT_STARTED'; end if;
  if v_event.ends_on is not null and v_today > v_event.ends_on then raise exception 'EVENT_ENDED'; end if;

  v_tier := public.current_tier_key(v_member.id);
  if not (v_tier = any(v_event.allowed_tier_keys)) then raise exception 'TIER_NOT_ALLOWED'; end if;

  if v_event.quota > 0 then
    select count(*)::integer into v_count from public.event_ticket_claims where event_ticket_id=v_event.id;
    if v_count >= v_event.quota then raise exception 'EVENT_QUOTA_REACHED'; end if;
  end if;

  v_claim_id := public.new_public_id('EC');
  insert into public.event_ticket_claims(
    claim_id,event_ticket_id,member_id,ticket_type,ticket_title,ticket_description,usage_method,usage_instructions,prizes
  ) values (
    v_claim_id,v_event.id,v_member.id,v_event.ticket_type,v_event.title,v_event.description,v_event.usage_method,v_event.usage_instructions,v_event.prizes
  );

  insert into public.audit_logs(audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result)
    values(public.new_public_id('AUD'),v_member.line_user_id,'member','user.event.ticket.claim','event_ticket',v_event.event_ticket_id,'success');

  return jsonb_build_object('claimId',v_claim_id,'alreadyClaimed',false);
end;
$function$
CREATE OR REPLACE FUNCTION public.classify_automation_test_failure_code()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  message_text text := lower(coalesce(new.failure_message, ''));
begin
  if new.status = 'failed'
     and (new.failure_code is null or new.failure_code in ('BROWSER_E2E_FAILED', 'UI_E2E_FAILED')) then
    new.failure_code := case
      when message_text ~ '(rate.?limit|too many requests|(^|[^0-9])429([^0-9]|$)|過於密集|稍後再試)'
        then 'E2E_RATE_LIMIT'
      when message_text ~ '(timeout|timed out|time out|deadline exceeded|允許時間|逾時|超時)'
        then 'E2E_TIMEOUT'
      when message_text ~ '(forbidden|permission denied|authorization|權限不足|無權限|不允許)'
        then 'E2E_AUTHORIZATION'
      when message_text ~ '(unauthenticated|authentication|invalid token|expired token|session expired|登入資訊|登入失效|重新登入|session required)'
        then 'E2E_AUTHENTICATION'
      when message_text ~ '(realtime|websocket|channel error|subscribe|subscription|即時同步)'
        then 'E2E_REALTIME'
      when message_text ~ '(failed to fetch|networkerror|network error|offline|connection reset|connection refused|網路)'
        then 'E2E_NETWORK'
      when message_text ~ '(service unavailable|internal server error|database|資料庫暫時|服務暫時)'
        then 'E2E_BACKEND'
      when message_text ~ '(window.error|unhandledrejection|typeerror|referenceerror|syntaxerror)'
        then 'E2E_CLIENT_ERROR'
      else 'E2E_ASSERTION'
    end;
  end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.cleanup_fixed_ticket_calendar_items_on_template_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_template_id uuid;
  v_should_cleanup boolean;
begin
  if tg_op = 'DELETE' then
    v_template_id := old.id;
    v_should_cleanup := true;
  else
    v_template_id := new.id;
    v_should_cleanup := new.deleted_at is not null
      or new.status <> 'active'
      or new.calendar_enabled is not true;
  end if;

  if v_should_cleanup then
    delete from public.calendar_items c
    using public.event_tickets e
    where c.source_event_ticket_id = e.id
      and e.fixed_ticket_template_id = v_template_id;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.complete_booking_with_benefits_request(p_booking_id uuid, p_expected_updated_at timestamp with time zone, p_actor text, p_admin_note text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_booking public.bookings%rowtype;
  v_member public.members%rowtype;
  v_selection public.booking_benefit_selections%rowtype;
  v_calendar public.calendar_items%rowtype;
  v_point_selection_ids uuid[];
  v_point_ids text[];
  v_event_ids text[];
  v_point_result jsonb := null;
  v_event_result jsonb := null;
  v_settlement jsonb;
  v_redemptions jsonb := '[]'::jsonb;
  v_tier text;
begin
  select * into v_booking
  from public.bookings
  where id = p_booking_id
  for update;

  if not found then raise exception 'BOOKING_NOT_FOUND'; end if;
  if p_expected_updated_at is null or v_booking.updated_at <> p_expected_updated_at then
    raise exception 'BOOKING_CONFLICT';
  end if;
  if v_booking.cancellation_requested_at is not null
     and v_booking.cancellation_reviewed_at is null then
    raise exception 'BOOKING_CANCELLATION_PENDING';
  end if;
  if v_booking.status <> 'confirmed' then
    raise exception 'INVALID_BOOKING_TRANSITION';
  end if;

  select * into v_member
  from public.members
  where id = v_booking.member_id
  for update;

  if not found
     or v_member.membership_status <> 'active'
     or v_member.status <> 'active' then
    raise exception 'MEMBERSHIP_REQUIRED';
  end if;

  select
    array_agg(id order by benefit_ref),
    array_agg(benefit_ref order by benefit_ref)
    into v_point_selection_ids, v_point_ids
  from public.booking_benefit_selections
  where booking_id = p_booking_id
    and status = 'pending'
    and benefit_kind = 'points';

  select array_agg(benefit_ref order by benefit_ref)
    into v_event_ids
  from public.booking_benefit_selections
  where booking_id = p_booking_id
    and status = 'pending'
    and benefit_kind = 'event';

  v_tier := public.current_tier_key(v_booking.member_id);
  for v_selection in
    select *
    from public.booking_benefit_selections
    where booking_id = p_booking_id
      and status = 'pending'
      and benefit_kind = 'calendar'
    order by benefit_ref
    for update
  loop
    select * into v_calendar
    from public.calendar_items
    where calendar_item_id = v_selection.benefit_ref
      and item_type = 'event';

    if not found
       or v_calendar.starts_on > v_booking.booking_date
       or coalesce(v_calendar.ends_on, v_calendar.starts_on) < v_booking.booking_date
       or (
         cardinality(v_calendar.allowed_tier_keys) > 0
         and not (v_tier = any(v_calendar.allowed_tier_keys))
       ) then
      raise exception 'BOOKING_BENEFIT_NOT_AVAILABLE';
    end if;

    if coalesce(v_calendar.audience_type, 'all') = 'birthday_month' then
      if v_calendar.status <> 'targeted'
         or v_member.birthday is null
         or extract(month from v_member.birthday)::int <> v_calendar.audience_month then
        raise exception 'BOOKING_BENEFIT_NOT_AVAILABLE';
      end if;
    elsif v_calendar.status <> 'active' then
      raise exception 'BOOKING_BENEFIT_NOT_AVAILABLE';
    end if;
  end loop;

  if coalesce(cardinality(v_point_ids), 0) > 0 then
    if exists (
      select 1
      from public.point_tickets pt
      where pt.member_id = v_booking.member_id
        and pt.ticket_id = any(v_point_ids)
        and coalesce(pt.requires_location, false)
    ) then
      raise exception 'BOOKING_BENEFIT_LOCATION_REQUIRED';
    end if;

    -- Release only this booking's held points inside the same transaction.
    -- Any later failure rolls this status change and the point redemption back together.
    update public.booking_benefit_selections
    set status = 'redeemed'
    where id = any(v_point_selection_ids)
      and status = 'pending'
      and benefit_kind = 'points';

    v_point_result := public.redeem_point_tickets(
      v_member.line_user_id,
      v_point_ids,
      'BOOKING_POINT_' || replace(p_booking_id::text, '-', '')
    );
  end if;

  if coalesce(cardinality(v_event_ids), 0) > 0 then
    v_event_result := public.redeem_event_tickets_with_location(
      v_member.line_user_id,
      v_event_ids,
      'BOOKING_EVENT_' || replace(p_booking_id::text, '-', ''),
      null
    );
  end if;

  v_settlement := public.complete_booking_with_rewards_request(
    p_booking_id,
    p_expected_updated_at,
    p_actor,
    left(coalesce(p_admin_note, ''), 500)
  );

  if coalesce(cardinality(v_point_selection_ids), 0) > 0 then
    update public.booking_benefit_selections
    set redeemed_at = now(),
        redeemed_by = p_actor,
        result = v_point_result
    where id = any(v_point_selection_ids)
      and status = 'redeemed'
      and benefit_kind = 'points';
  end if;

  update public.booking_benefit_selections
  set status = 'redeemed',
      redeemed_at = now(),
      redeemed_by = p_actor,
      result = v_event_result
  where booking_id = p_booking_id
    and status = 'pending'
    and benefit_kind = 'event';

  update public.booking_benefit_selections
  set status = 'applied',
      redeemed_at = now(),
      redeemed_by = p_actor,
      result = jsonb_build_object('activityApplied', true)
  where booking_id = p_booking_id
    and status = 'pending'
    and benefit_kind = 'calendar';

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'kind', benefit_kind,
        'id', benefit_ref,
        'title', title_snapshot,
        'status', status,
        'result', result
      )
      order by selected_at, id
    ),
    '[]'::jsonb
  )
    into v_redemptions
  from public.booking_benefit_selections
  where booking_id = p_booking_id
    and status in ('redeemed', 'applied');

  insert into public.audit_logs(
    audit_id,
    actor_line_user_id,
    actor_role,
    action,
    target_type,
    target_id,
    result,
    detail
  ) values (
    public.new_public_id('AUD'),
    p_actor,
    'admin',
    'admin.booking.benefits.redeem',
    'booking',
    p_booking_id::text,
    'success',
    jsonb_build_object('redemptions', v_redemptions)
  );

  return coalesce(v_settlement, '{}'::jsonb)
    || jsonb_build_object('redemptions', v_redemptions);
end;
$function$
CREATE OR REPLACE FUNCTION public.complete_booking_with_receipt_request(p_receipt_id text, p_member_id uuid, p_actor_line_user_id text, p_expected_booking_updated_at timestamp with time zone, p_actual_mime_type text, p_actual_size_bytes integer, p_sha256_hex text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  return public.finalize_booking_receipt_request(
    p_receipt_id,
    p_member_id,
    p_actor_line_user_id,
    p_expected_booking_updated_at,
    p_actual_mime_type,
    p_actual_size_bytes,
    p_sha256_hex
  );
end;
$function$
CREATE OR REPLACE FUNCTION public.complete_booking_with_rewards_request(p_booking_id uuid, p_expected_updated_at timestamp with time zone, p_actor text, p_admin_note text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_booking public.bookings%rowtype;
  v_primary_technician_id uuid;
  v_request_id text := 'booking-complete:' || p_booking_id::text;
  v_service_minutes integer := 0;
  v_reward_details jsonb := '[]'::jsonb;
  v_reward record;
  v_card public.point_cards%rowtype;
  v_rows integer := 0;
  v_now timestamptz := now();
begin
  select * into v_booking
  from public.bookings
  where id = p_booking_id
  for update;

  if not found then
    raise exception 'BOOKING_NOT_FOUND';
  end if;

  if p_expected_updated_at is null or v_booking.updated_at <> p_expected_updated_at then
    raise exception 'BOOKING_CONFLICT';
  end if;

  if v_booking.cancellation_requested_at is not null
     and v_booking.cancellation_reviewed_at is null then
    raise exception 'BOOKING_CANCELLATION_PENDING';
  end if;

  if v_booking.status <> 'confirmed' then
    raise exception 'INVALID_BOOKING_TRANSITION';
  end if;

  if exists (
    select 1
    from public.booking_completion_settlements
    where booking_id = p_booking_id
  ) then
    raise exception 'BOOKING_COMPLETION_ALREADY_SETTLED';
  end if;

  select primary_technician_id
    into v_primary_technician_id
  from public.booking_settings
  where id = 1;

  if v_primary_technician_id is null then
    raise exception 'BOOKING_PRIMARY_TECHNICIAN_MISSING';
  end if;

  if not exists (
    select 1
    from public.booking_participants bp
    where bp.booking_id = p_booking_id
      and bp.technician_id = v_primary_technician_id
  ) then
    raise exception 'BOOKING_PRIMARY_TECHNICIAN_REQUIRED';
  end if;

  with eligible_items as (
    select
      bpi.service_id,
      bpi.unit_duration_minutes,
      greatest(coalesce(bpi.quantity, 1), 1)::integer as quantity,
      coalesce(
        nullif(btrim(coalesce(bi.service_type, '')), ''),
        nullif(btrim(coalesce(bs.service_type, '')), '')
      ) as service_type,
      coalesce(bi.counts_toward_membership, bs.counts_toward_membership, true) as counts_toward_membership
    from public.booking_participants bp
    join public.booking_participant_items bpi
      on bpi.participant_id = bp.id
    left join public.booking_items bi
      on bi.booking_id = bp.booking_id
     and bi.service_id = bpi.service_id
    left join public.booking_services bs
      on bs.id = bpi.service_id
    where bp.booking_id = p_booking_id
      and bp.technician_id = v_primary_technician_id
      and bpi.service_id <> '00000000-0000-4000-8000-000000000010'::uuid
  )
  select coalesce(sum(ei.unit_duration_minutes * ei.quantity), 0)::integer
    into v_service_minutes
  from eligible_items ei
  where ei.counts_toward_membership = true;

  for v_reward in
    with eligible_items as (
      select
        bpi.service_id,
        bpi.unit_duration_minutes,
        greatest(coalesce(bpi.quantity, 1), 1)::integer as quantity,
        coalesce(
          nullif(btrim(coalesce(bi.service_type, '')), ''),
          nullif(btrim(coalesce(bs.service_type, '')), '')
        ) as service_type,
        coalesce(bi.counts_toward_membership, bs.counts_toward_membership, true) as counts_toward_membership
      from public.booking_participants bp
      join public.booking_participant_items bpi
        on bpi.participant_id = bp.id
      left join public.booking_items bi
        on bi.booking_id = bp.booking_id
       and bi.service_id = bpi.service_id
      left join public.booking_services bs
        on bs.id = bpi.service_id
      where bp.booking_id = p_booking_id
        and bp.technician_id = v_primary_technician_id
        and bpi.service_id <> '00000000-0000-4000-8000-000000000010'::uuid
    ),
    type_minutes as (
      select
        lower(btrim(ei.service_type)) as type_key,
        sum(ei.unit_duration_minutes * ei.quantity)::integer as service_minutes
      from eligible_items ei
      where ei.counts_toward_membership = true
        and nullif(btrim(coalesce(ei.service_type, '')), '') is not null
      group by lower(btrim(ei.service_type))
    )
    select
      t.id as service_type_id,
      t.name as service_type_name,
      tm.service_minutes,
      r.minutes_per_point,
      r.point_card_id,
      floor(tm.service_minutes::numeric / r.minutes_per_point)::integer as points
    from type_minutes tm
    join public.booking_service_types t
      on lower(btrim(t.name)) = tm.type_key
    join public.booking_service_type_rewards r
      on r.service_type_id = t.id
    where floor(tm.service_minutes::numeric / r.minutes_per_point)::integer > 0
    order by t.sort_order, t.created_at
  loop
    select * into v_card
    from public.point_cards
    where id = v_reward.point_card_id
    for update;

    if not found
       or v_card.status <> 'active'
       or (v_card.expiry_mode <> 'unlimited'
           and (v_card.expires_on is null
                or v_card.expires_on < (clock_timestamp() at time zone 'Asia/Taipei')::date)) then
      raise exception 'BOOKING_REWARD_POINT_CARD_UNAVAILABLE';
    end if;

    v_reward_details := v_reward_details || jsonb_build_array(
      jsonb_build_object(
        'serviceTypeId', v_reward.service_type_id,
        'serviceTypeName', v_reward.service_type_name,
        'serviceMinutes', v_reward.service_minutes,
        'minutesPerPoint', v_reward.minutes_per_point,
        'pointCardId', v_card.id,
        'pointCardPublicId', v_card.card_id,
        'pointCardTitle', v_card.title,
        'points', v_reward.points
      )
    );
  end loop;

  if v_service_minutes > 0 then
    insert into public.service_time_entries(
      entry_id, member_id, minutes, note, created_by, request_id
    )
    values (
      public.new_public_id('SE'),
      v_booking.member_id,
      v_service_minutes,
      '預約完成自動加入服務時間（僅主要技師項目）',
      p_actor,
      v_request_id
    )
    on conflict (request_id, member_id)
      where request_id is not null and request_id <> ''
    do nothing;

    get diagnostics v_rows = row_count;
    if v_rows <> 1 then
      raise exception 'BOOKING_COMPLETION_SERVICE_TIME_CONFLICT';
    end if;
  end if;

  for v_reward in
    with eligible_items as (
      select
        bpi.service_id,
        bpi.unit_duration_minutes,
        greatest(coalesce(bpi.quantity, 1), 1)::integer as quantity,
        coalesce(
          nullif(btrim(coalesce(bi.service_type, '')), ''),
          nullif(btrim(coalesce(bs.service_type, '')), '')
        ) as service_type,
        coalesce(bi.counts_toward_membership, bs.counts_toward_membership, true) as counts_toward_membership
      from public.booking_participants bp
      join public.booking_participant_items bpi
        on bpi.participant_id = bp.id
      left join public.booking_items bi
        on bi.booking_id = bp.booking_id
       and bi.service_id = bpi.service_id
      left join public.booking_services bs
        on bs.id = bpi.service_id
      where bp.booking_id = p_booking_id
        and bp.technician_id = v_primary_technician_id
        and bpi.service_id <> '00000000-0000-4000-8000-000000000010'::uuid
    ),
    type_minutes as (
      select
        lower(btrim(ei.service_type)) as type_key,
        sum(ei.unit_duration_minutes * ei.quantity)::integer as service_minutes
      from eligible_items ei
      where ei.counts_toward_membership = true
        and nullif(btrim(coalesce(ei.service_type, '')), '') is not null
      group by lower(btrim(ei.service_type))
    ),
    per_type as (
      select
        r.point_card_id,
        floor(tm.service_minutes::numeric / r.minutes_per_point)::integer as points
      from type_minutes tm
      join public.booking_service_types t
        on lower(btrim(t.name)) = tm.type_key
      join public.booking_service_type_rewards r
        on r.service_type_id = t.id
    )
    select point_card_id, sum(points)::integer as points
    from per_type
    where points > 0
    group by point_card_id
  loop
    insert into public.point_entries(
      entry_id, member_id, point_card_id, amount, note, created_by,
      request_id, entry_type, reference_type, reference_id
    )
    values (
      public.new_public_id('PE'),
      v_booking.member_id,
      v_reward.point_card_id,
      v_reward.points,
      '預約完成自動集點（僅主要技師項目）',
      p_actor,
      v_request_id,
      'grant',
      'booking',
      p_booking_id::text
    )
    on conflict (request_id, member_id, point_card_id)
      where request_id is not null and request_id <> ''
    do nothing;

    get diagnostics v_rows = row_count;
    if v_rows <> 1 then
      raise exception 'BOOKING_COMPLETION_POINT_CONFLICT';
    end if;

    insert into public.point_balances(member_id, point_card_id, stamps, updated_at)
    values (v_booking.member_id, v_reward.point_card_id, v_reward.points, v_now)
    on conflict (member_id, point_card_id)
    do update
      set stamps = public.point_balances.stamps + excluded.stamps,
          updated_at = v_now;

    perform public.issue_eligible_point_tickets(v_booking.member_id, v_reward.point_card_id);
  end loop;

  insert into public.booking_completion_settlements(
    booking_id, member_id, service_minutes, reward_details, completed_by, created_at
  )
  values (
    p_booking_id,
    v_booking.member_id,
    v_service_minutes,
    v_reward_details,
    p_actor,
    v_now
  );

  update public.bookings
  set status = 'completed',
      admin_note = left(coalesce(p_admin_note, ''), 500),
      completed_by = p_actor,
      completed_at = v_now
  where id = p_booking_id
    and status = 'confirmed'
    and updated_at = p_expected_updated_at;

  if not found then
    raise exception 'BOOKING_CONFLICT';
  end if;

  return jsonb_build_object(
    'bookingId', p_booking_id,
    'primaryTechnicianId', v_primary_technician_id,
    'serviceMinutes', v_service_minutes,
    'rewards', v_reward_details
  );
end;
$function$
CREATE OR REPLACE FUNCTION public.consume_api_rate_limit(p_principal_hash text, p_is_write boolean, p_cost integer DEFAULT 1, p_read_limit integer DEFAULT 90, p_write_limit integer DEFAULT 30)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_bucket timestamptz := date_trunc('minute', now());
  v_qa_mode boolean := false;
  v_multiplier integer := 1;
  v_effective_principal_hash text := p_principal_hash;
  v_type text := case when p_is_write then 'write' else 'read' end;
  v_limit integer;
  v_count integer;
begin
  if p_cost < 1 or p_cost > 20 then
    return false;
  end if;

  select coalesce(settings.enabled, false) and coalesce(settings.maintenance_enabled, false)
    into v_qa_mode
  from public.test_mode_settings as settings
  where settings.id = true;

  v_qa_mode := coalesce(v_qa_mode, false);
  if v_qa_mode then
    v_multiplier := 8;
    v_effective_principal_hash := 'qa:' || p_principal_hash;
  end if;

  v_limit := greatest(
    1,
    (case when p_is_write then p_write_limit else p_read_limit end) * v_multiplier
  );

  insert into public.api_rate_limits(principal_hash, bucket_at, bucket_type, request_count)
  values(v_effective_principal_hash, v_bucket, v_type, p_cost)
  on conflict(principal_hash, bucket_at, bucket_type)
  do update set request_count = public.api_rate_limits.request_count + excluded.request_count
  returning request_count into v_count;

  delete from public.api_rate_limits
  where bucket_at < now() - interval '2 hours';

  return v_count <= v_limit;
end;
$function$
CREATE OR REPLACE FUNCTION public.count_today_usable_event_tickets(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_member public.members%rowtype;
  v_tier text;
  v_today date := (clock_timestamp() at time zone 'Asia/Taipei')::date;
  v_day_start timestamptz := (v_today::timestamp at time zone 'Asia/Taipei');
  v_day_end timestamptz := ((v_today + 1)::timestamp at time zone 'Asia/Taipei');
  v_available_count integer := 0;
  v_used_today_count integer := 0;
  v_max_tickets integer := 1;
  v_remaining_today integer := 0;
begin
  select * into v_member
  from public.members
  where line_user_id=p_line_user_id
    and status='active'
    and membership_status='active';
  if not found then raise exception 'MEMBERSHIP_REQUIRED'; end if;

  v_tier:=public.current_tier_key(v_member.id);

  select coalesce(max_tickets_per_day, max_tickets_per_redemption, 1)
    into v_max_tickets
  from public.event_ticket_settings
  where id=1;
  v_max_tickets := coalesce(v_max_tickets,1);

  select count(*)::integer into v_used_today_count
  from public.event_ticket_claims c
  where c.member_id=v_member.id
    and c.status='used'
    and c.used_at >= v_day_start
    and c.used_at < v_day_end;

  select count(*)::integer into v_available_count
  from public.event_ticket_claims c
  join public.event_tickets e on e.id=c.event_ticket_id
  where c.member_id=v_member.id
    and c.status='claimed'
    and e.deleted_at is null
    and e.status='active'
    and (e.starts_on is null or e.starts_on<=v_today)
    and (e.ends_on is null or e.ends_on>=v_today)
    and v_tier=any(e.allowed_tier_keys);

  if v_max_tickets = 0 then
    v_remaining_today := v_available_count;
  else
    v_remaining_today := greatest(v_max_tickets - v_used_today_count, 0);
  end if;

  return jsonb_build_object(
    'businessDate',v_today,
    'availableTodayCount',v_available_count,
    'usedTodayCount',v_used_today_count,
    'remainingTodayCount',v_remaining_today,
    'maxTicketsPerDay',v_max_tickets,
    'maxTicketsPerRedemption',v_max_tickets,
    'todayUsableCount',least(v_available_count,v_remaining_today)
  );
end;
$function$
CREATE OR REPLACE FUNCTION public.create_booking_bundle_request(p_request_id text, p_member_id uuid, p_booking_date date, p_start_time time without time zone, p_items jsonb, p_member_note text DEFAULT ''::text)
 RETURNS bookings
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_settings public.booking_settings%rowtype;
  v_member public.members%rowtype;
  v_existing public.bookings%rowtype;
  v_booking public.bookings%rowtype;
  v_service public.booking_services%rowtype;
  v_item jsonb;
  v_service_id uuid;
  v_primary_service_id uuid;
  v_seen_service_ids uuid[] := array[]::uuid[];
  v_quantity integer;
  v_total_duration integer := 0;
  v_today date := (now() at time zone 'Asia/Taipei')::date;
  v_local_time time := (now() at time zone 'Asia/Taipei')::time;
  v_end_time time;
  v_item_count integer;
  v_participant_id uuid;
begin
  if p_request_id is null or char_length(btrim(p_request_id)) < 12 or char_length(p_request_id) > 100 then
    raise exception 'INVALID_REQUEST_ID';
  end if;

  select * into v_existing
  from public.bookings
  where request_id = p_request_id;

  if found then
    if v_existing.member_id <> p_member_id then
      raise exception 'REQUEST_ID_CONFLICT';
    end if;
    return v_existing;
  end if;

  select * into v_member
  from public.members
  where id = p_member_id;

  if not found then raise exception 'MEMBER_NOT_FOUND'; end if;
  if coalesce(v_member.membership_status, '') <> 'active' then raise exception 'MEMBERSHIP_REQUIRED'; end if;
  if coalesce(v_member.status, '') <> 'active' then raise exception 'MEMBER_DISABLED'; end if;

  select * into v_settings
  from public.booking_settings
  where id = 1
  for share;
  if not found then raise exception 'BOOKING_SETTINGS_MISSING'; end if;
  if v_settings.primary_technician_id is null
     or not exists (
       select 1
       from public.booking_technicians
       where id = v_settings.primary_technician_id
         and is_active = true
     ) then
    raise exception 'BOOKING_PRIMARY_TECHNICIAN_REQUIRED';
  end if;

  if jsonb_typeof(p_items) <> 'array' then raise exception 'INVALID_BOOKING_ITEMS'; end if;
  v_item_count := jsonb_array_length(p_items);
  if v_item_count < 1 or v_item_count > 20 then raise exception 'INVALID_BOOKING_ITEMS'; end if;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    begin
      v_service_id := (v_item ->> 'serviceId')::uuid;
      v_quantity := coalesce((v_item ->> 'quantity')::integer, 1);
    exception when others then
      raise exception 'INVALID_BOOKING_ITEMS';
    end;

    if v_quantity < 1 or v_quantity > 2 then raise exception 'INVALID_BOOKING_QUANTITY'; end if;
    if v_service_id = any(v_seen_service_ids) then raise exception 'DUPLICATE_BOOKING_SERVICE'; end if;
    v_seen_service_ids := array_append(v_seen_service_ids, v_service_id);

    select * into v_service
    from public.booking_services
    where id = v_service_id
    for share;
    if not found then raise exception 'BOOKING_SERVICE_NOT_FOUND'; end if;
    if not v_service.is_active then raise exception 'BOOKING_SERVICE_DISABLED'; end if;

    if v_primary_service_id is null then v_primary_service_id := v_service_id; end if;
    v_total_duration := v_total_duration + (v_service.duration_minutes * v_quantity);
  end loop;

  if v_total_duration < 1 or v_total_duration > 1440 then raise exception 'INVALID_BOOKING_DURATION'; end if;
  if p_booking_date < public.booking_business_date(clock_timestamp() at time zone 'Asia/Taipei',v_settings.work_start_time,v_settings.work_end_time) + coalesce(v_settings.min_advance_days,0) then raise exception 'BOOKING_TOO_EARLY'; end if;
  if public.booking_slot_start_at(p_booking_date,p_start_time,v_settings.work_start_time,v_settings.work_end_time) <= (clock_timestamp() at time zone 'Asia/Taipei') then raise exception 'BOOKING_TIME_PASSED'; end if;
  if extract(second from p_start_time) <> 0 then raise exception 'INVALID_BOOKING_SLOT'; end if;

  v_end_time := p_start_time + make_interval(mins => v_total_duration);
  if not public.booking_slot_fits(p_booking_date,p_start_time,v_total_duration,v_settings.work_start_time,v_settings.work_end_time,v_settings.slot_interval_minutes) then
    raise exception 'INVALID_BOOKING_SLOT';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_booking_date::text, 0));

  begin
    insert into public.bookings(
      request_id, service_id, member_id, booking_date, start_time, end_time,
      total_duration_minutes, status, member_note, technician_id
    ) values (
      btrim(p_request_id), v_primary_service_id, p_member_id, p_booking_date,
      p_start_time, v_end_time, v_total_duration, 'pending',
      left(coalesce(p_member_note, ''), 500),
      v_settings.primary_technician_id
    )
    returning * into v_booking;
  exception
    when exclusion_violation or unique_violation then
      raise exception 'BOOKING_SLOT_TAKEN';
  end;

  insert into public.booking_participants(
    booking_id, position, technician_id
  ) values (
    v_booking.id, 1, v_settings.primary_technician_id
  )
  returning id into v_participant_id;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    v_service_id := (v_item ->> 'serviceId')::uuid;
    v_quantity := coalesce((v_item ->> 'quantity')::integer, 1);

    select * into v_service
    from public.booking_services
    where id = v_service_id;

    insert into public.booking_items(
      booking_id, service_id, service_title,
      unit_duration_minutes, unit_price_amount, quantity,
      service_type, counts_toward_membership
    ) values (
      v_booking.id, v_service.id, v_service.title,
      v_service.duration_minutes, v_service.price_amount, v_quantity,
      v_service.service_type, v_service.counts_toward_membership
    );

    insert into public.booking_participant_items(
      participant_id, service_id, service_title,
      unit_duration_minutes, unit_price_amount, quantity
    ) values (
      v_participant_id, v_service.id, v_service.title,
      v_service.duration_minutes, v_service.price_amount, v_quantity
    );
  end loop;

  insert into public.booking_participant_reservations(
    participant_id, booking_id, technician_id,
    booking_date, start_time, end_time, is_active
  ) values (
    v_participant_id, v_booking.id, v_settings.primary_technician_id,
    v_booking.booking_date, v_booking.start_time, v_booking.end_time, true
  );

  return v_booking;
end;
$function$
CREATE OR REPLACE FUNCTION public.create_booking_bundle_with_benefits_request(p_request_id text, p_member_id uuid, p_booking_date date, p_start_time time without time zone, p_items jsonb, p_member_note text, p_benefits jsonb DEFAULT '[]'::jsonb)
 RETURNS bookings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_booking public.bookings%rowtype;
begin
  select * into v_booking
  from public.create_booking_bundle_request(
    p_request_id,p_member_id,p_booking_date,p_start_time,p_items,p_member_note
  );
  perform public.replace_booking_benefit_selections_request(v_booking.id,p_member_id,p_benefits);
  return v_booking;
end;
$function$
CREATE OR REPLACE FUNCTION public.create_booking_bundle_with_contact(p_request_id text, p_member_id uuid, p_booking_date date, p_start_time time without time zone, p_items jsonb, p_member_note text DEFAULT ''::text, p_contact_source text DEFAULT 'member'::text, p_contact_surname text DEFAULT ''::text, p_contact_salutation text DEFAULT ''::text, p_contact_phone text DEFAULT ''::text)
 RETURNS bookings
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_member public.members%rowtype;
  v_booking public.bookings%rowtype;
  v_source text := lower(btrim(coalesce(p_contact_source, '')));
  v_surname text;
  v_salutation text;
  v_phone text;
begin
  select * into v_member from public.members where id = p_member_id;
  if not found then raise exception 'MEMBER_NOT_FOUND'; end if;

  if v_source = 'member' then
    v_surname := btrim(coalesce(v_member.surname, ''));
    v_salutation := lower(btrim(coalesce(v_member.salutation, '')));
    v_phone := regexp_replace(btrim(coalesce(v_member.phone, '')), '[()[:space:]-]', '', 'g');
  elsif v_source = 'custom' then
    v_surname := btrim(coalesce(p_contact_surname, ''));
    v_salutation := lower(btrim(coalesce(p_contact_salutation, '')));
    v_phone := regexp_replace(btrim(coalesce(p_contact_phone, '')), '[()[:space:]-]', '', 'g');
  else
    raise exception 'INVALID_BOOKING_CONTACT_SOURCE';
  end if;

  if char_length(v_surname) < 1 or char_length(v_surname) > 40 then raise exception 'INVALID_BOOKING_CONTACT_SURNAME'; end if;
  if v_salutation not in ('mr','ms') then raise exception 'INVALID_BOOKING_CONTACT_SALUTATION'; end if;
  if v_phone !~ '^\+?[0-9]{8,15}$' then raise exception 'INVALID_BOOKING_CONTACT_PHONE'; end if;

  v_booking := public.create_booking_bundle_request(
    p_request_id, p_member_id, p_booking_date, p_start_time, p_items, p_member_note
  );

  if v_booking.contact_surname is not null or v_booking.contact_salutation is not null or v_booking.contact_phone is not null then
    if v_booking.contact_source <> v_source
       or coalesce(v_booking.contact_surname, '') <> v_surname
       or coalesce(v_booking.contact_salutation, '') <> v_salutation
       or coalesce(v_booking.contact_phone, '') <> v_phone then
      raise exception 'REQUEST_ID_CONFLICT';
    end if;
    return v_booking;
  end if;

  update public.bookings
  set contact_source = v_source,
      contact_surname = v_surname,
      contact_salutation = v_salutation,
      contact_phone = v_phone
  where id = v_booking.id
  returning * into v_booking;

  return v_booking;
end;
$function$
CREATE OR REPLACE FUNCTION public.create_booking_request(p_request_id text, p_service_id uuid, p_member_id uuid, p_booking_date date, p_start_time time without time zone, p_member_note text DEFAULT ''::text)
 RETURNS bookings
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  return public.create_booking_bundle_request(
    p_request_id,
    p_member_id,
    p_booking_date,
    p_start_time,
    jsonb_build_array(
      jsonb_build_object('serviceId', p_service_id, 'quantity', 1),
      jsonb_build_object('serviceId', '00000000-0000-4000-8000-000000000010'::uuid, 'quantity', 1)
    ),
    p_member_note
  );
end;
$function$
CREATE OR REPLACE FUNCTION public.create_group_booking_request(p_request_id text, p_member_id uuid, p_booking_date date, p_start_time time without time zone, p_technician_id uuid, p_participants jsonb, p_member_note text DEFAULT ''::text, p_contact_source text DEFAULT 'member'::text, p_contact_surname text DEFAULT NULL::text, p_contact_salutation text DEFAULT NULL::text, p_contact_phone text DEFAULT NULL::text)
 RETURNS bookings
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_settings public.booking_settings%rowtype;
  v_member public.members%rowtype;
  v_existing public.bookings%rowtype;
  v_booking public.bookings%rowtype;
  v_technician public.booking_technicians%rowtype;
  v_service public.booking_services%rowtype;
  v_store public.booking_services%rowtype;
  v_participant jsonb;
  v_item jsonb;
  v_participant_id uuid;
  v_service_id uuid;
  v_primary_service_id uuid;
  v_seen uuid[];
  v_quantity integer;
  v_party_size integer;
  v_position integer := 0;
  v_total_duration integer := 0;
  v_participant_duration integer := 0;
  v_today date := (now() at time zone 'Asia/Taipei')::date;
  v_local_time time := (now() at time zone 'Asia/Taipei')::time;
  v_end_time time;
begin
  if p_request_id is null or char_length(btrim(p_request_id)) < 12 or char_length(p_request_id) > 100 then raise exception 'INVALID_REQUEST_ID'; end if;
  select * into v_existing from public.bookings where request_id = p_request_id;
  if found then
    if v_existing.member_id <> p_member_id then raise exception 'REQUEST_ID_CONFLICT'; end if;
    return v_existing;
  end if;

  select * into v_member from public.members where id = p_member_id;
  if not found then raise exception 'MEMBER_NOT_FOUND'; end if;
  if coalesce(v_member.membership_status,'') <> 'active' then raise exception 'MEMBERSHIP_REQUIRED'; end if;
  if coalesce(v_member.status,'') <> 'active' then raise exception 'MEMBER_DISABLED'; end if;

  select * into v_settings from public.booking_settings where id = 1 for share;
  if not found then raise exception 'BOOKING_SETTINGS_MISSING'; end if;

  if p_participants is null or jsonb_typeof(p_participants) <> 'array' then raise exception 'INVALID_BOOKING_PARTICIPANTS'; end if;
  v_party_size := jsonb_array_length(p_participants);
  if v_party_size < 1 or v_party_size > v_settings.max_party_size then raise exception 'INVALID_PARTY_SIZE'; end if;

  select * into v_technician from public.booking_technicians where id = p_technician_id for share;
  if not found then raise exception 'BOOKING_TECHNICIAN_NOT_FOUND'; end if;
  if not v_technician.is_active then raise exception 'BOOKING_TECHNICIAN_DISABLED'; end if;

  for v_participant in select value from jsonb_array_elements(p_participants) loop
    v_position := v_position + 1;
    v_participant_duration := 0;
    if jsonb_typeof(v_participant->'items') <> 'array' or jsonb_array_length(v_participant->'items') < 1 or jsonb_array_length(v_participant->'items') > 20 then
      raise exception 'INVALID_BOOKING_ITEMS';
    end if;
    v_seen := array[]::uuid[];
    for v_item in select value from jsonb_array_elements(v_participant->'items') loop
      begin
        v_service_id := (v_item->>'serviceId')::uuid;
        v_quantity := coalesce((v_item->>'quantity')::integer,1);
      exception when others then raise exception 'INVALID_BOOKING_ITEMS'; end;
      if v_service_id = '00000000-0000-4000-8000-000000000010' then raise exception 'INVALID_BOOKING_ITEMS'; end if;
      if v_quantity < 1 or v_quantity > 2 then raise exception 'INVALID_BOOKING_QUANTITY'; end if;
      if v_service_id = any(v_seen) then raise exception 'DUPLICATE_BOOKING_SERVICE'; end if;
      v_seen := array_append(v_seen, v_service_id);
      select * into v_service from public.booking_services where id = v_service_id for share;
      if not found then raise exception 'BOOKING_SERVICE_NOT_FOUND'; end if;
      if not v_service.is_active then raise exception 'BOOKING_SERVICE_DISABLED'; end if;
      if v_primary_service_id is null then v_primary_service_id := v_service_id; end if;
      v_participant_duration := v_participant_duration + (v_service.duration_minutes * v_quantity);
    end loop;
    v_total_duration := greatest(v_total_duration, v_participant_duration);
  end loop;

  select * into v_store from public.booking_services where id = '00000000-0000-4000-8000-000000000010' for share;
  if not found then raise exception 'BOOKING_SERVICE_NOT_FOUND'; end if;
  if not v_store.is_active then raise exception 'BOOKING_SERVICE_DISABLED'; end if;
  v_total_duration := v_total_duration + v_store.duration_minutes;

  if v_total_duration < 1 or v_total_duration > 1440 then raise exception 'INVALID_BOOKING_DURATION'; end if;
  if p_booking_date < public.booking_business_date(clock_timestamp() at time zone 'Asia/Taipei',v_settings.work_start_time,v_settings.work_end_time) + coalesce(v_settings.min_advance_days,0) then raise exception 'BOOKING_TOO_EARLY'; end if;
  if public.booking_slot_start_at(p_booking_date,p_start_time,v_settings.work_start_time,v_settings.work_end_time) <= (clock_timestamp() at time zone 'Asia/Taipei') then raise exception 'BOOKING_TIME_PASSED'; end if;
  if extract(second from p_start_time) <> 0 then raise exception 'INVALID_BOOKING_SLOT'; end if;
  v_end_time := p_start_time + make_interval(mins => v_total_duration);
  if not public.booking_slot_fits(p_booking_date,p_start_time,v_total_duration,v_settings.work_start_time,v_settings.work_end_time,v_settings.slot_interval_minutes) then raise exception 'INVALID_BOOKING_SLOT'; end if;

  if p_contact_source not in ('member','custom') then raise exception 'INVALID_BOOKING_CONTACT'; end if;
  if p_contact_source = 'custom' and (nullif(btrim(coalesce(p_contact_surname,'')),'') is null or p_contact_salutation not in ('mr','ms') or nullif(btrim(coalesce(p_contact_phone,'')),'') is null) then
    raise exception 'INVALID_BOOKING_CONTACT';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_booking_date::text || ':' || p_technician_id::text,0));
  begin
    insert into public.bookings(
      request_id, service_id, member_id, booking_date, start_time, end_time, total_duration_minutes,
      status, member_note, technician_id, party_size, contact_source, contact_surname, contact_salutation, contact_phone
    ) values (
      btrim(p_request_id), v_primary_service_id, p_member_id, p_booking_date, p_start_time, v_end_time, v_total_duration,
      'pending', left(coalesce(p_member_note,''),500), p_technician_id, v_party_size, p_contact_source,
      case when p_contact_source='custom' then left(btrim(p_contact_surname),40) else null end,
      case when p_contact_source='custom' then p_contact_salutation else null end,
      case when p_contact_source='custom' then left(btrim(p_contact_phone),20) else null end
    ) returning * into v_booking;
  exception when exclusion_violation or unique_violation then raise exception 'BOOKING_SLOT_TAKEN'; end;

  v_position := 0;
  for v_participant in select value from jsonb_array_elements(p_participants) loop
    v_position := v_position + 1;
    insert into public.booking_participants(booking_id, position) values (v_booking.id, v_position) returning id into v_participant_id;
    for v_item in select value from jsonb_array_elements(v_participant->'items') loop
      v_service_id := (v_item->>'serviceId')::uuid;
      v_quantity := coalesce((v_item->>'quantity')::integer,1);
      select * into v_service from public.booking_services where id = v_service_id;
      insert into public.booking_participant_items(participant_id, service_id, service_title, unit_duration_minutes, unit_price_amount, quantity)
      values (v_participant_id, v_service.id, v_service.title, v_service.duration_minutes, v_service.price_amount, v_quantity);
      insert into public.booking_items(booking_id, service_id, service_title, unit_duration_minutes, unit_price_amount, quantity, service_type, counts_toward_membership)
      values (v_booking.id, v_service.id, v_service.title, v_service.duration_minutes, v_service.price_amount, v_quantity, v_service.service_type, v_service.counts_toward_membership)
      on conflict (booking_id, service_id) do update set quantity = public.booking_items.quantity + excluded.quantity;
    end loop;
  end loop;

  insert into public.booking_items(booking_id, service_id, service_title, unit_duration_minutes, unit_price_amount, quantity, service_type, counts_toward_membership)
  values (v_booking.id, v_store.id, v_store.title, v_store.duration_minutes, v_store.price_amount, 1, v_store.service_type, v_store.counts_toward_membership)
  on conflict (booking_id, service_id) do update set quantity = excluded.quantity;

  return v_booking;
end;
$function$
CREATE OR REPLACE FUNCTION public.create_group_booking_request_v2(p_request_id text, p_member_id uuid, p_booking_date date, p_start_time time without time zone, p_participants jsonb, p_member_note text DEFAULT ''::text, p_contact_source text DEFAULT 'member'::text, p_contact_surname text DEFAULT NULL::text, p_contact_salutation text DEFAULT NULL::text, p_contact_phone text DEFAULT NULL::text)
 RETURNS bookings
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_primary_technician_id uuid;
  v_booking public.bookings%rowtype;
  v_participant jsonb;
  v_position integer;
  v_participant_id uuid;
  v_technician_id uuid;
  v_duration integer;
begin
  v_primary_technician_id := public.validate_group_booking_technicians(p_participants);

  v_booking := public.create_group_booking_request(
    p_request_id,
    p_member_id,
    p_booking_date,
    p_start_time,
    v_primary_technician_id,
    p_participants,
    p_member_note,
    p_contact_source,
    p_contact_surname,
    p_contact_salutation,
    p_contact_phone
  );

  for v_participant, v_position in
    select value, ordinality::integer
    from jsonb_array_elements(p_participants) with ordinality
  loop
    select id into v_participant_id
    from public.booking_participants
    where booking_id = v_booking.id and position = v_position;
    if not found then raise exception 'INVALID_BOOKING_PARTICIPANTS'; end if;

    v_technician_id := null;
    if nullif(btrim(coalesce(v_participant->>'technicianId','')), '') is not null then
      v_technician_id := (v_participant->>'technicianId')::uuid;
    end if;

    update public.booking_participants
    set technician_id = v_technician_id
    where id = v_participant_id;

    delete from public.booking_participant_reservations where participant_id = v_participant_id;
    if v_technician_id is not null then
      select coalesce(sum(unit_duration_minutes * quantity), 0)::integer
      into v_duration
      from public.booking_participant_items
      where participant_id = v_participant_id;

      if v_duration < 1 then raise exception 'INVALID_BOOKING_DURATION'; end if;

      insert into public.booking_participant_reservations(
        participant_id, booking_id, technician_id, booking_date, start_time, end_time, is_active
      ) values (
        v_participant_id,
        v_booking.id,
        v_technician_id,
        v_booking.booking_date,
        v_booking.start_time,
        v_booking.start_time + make_interval(mins => v_duration),
        v_booking.status in ('pending','confirmed')
      );
    end if;
  end loop;

  return v_booking;
exception
  when exclusion_violation then
    raise exception 'BOOKING_SLOT_TAKEN';
end;
$function$
CREATE OR REPLACE FUNCTION public.create_group_booking_with_benefits_request_v2(p_request_id text, p_member_id uuid, p_booking_date date, p_start_time time without time zone, p_participants jsonb, p_member_note text, p_contact_source text, p_contact_surname text, p_contact_salutation text, p_contact_phone text, p_benefits jsonb DEFAULT '[]'::jsonb)
 RETURNS bookings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_booking public.bookings%rowtype;
begin
  select * into v_booking
  from public.create_group_booking_request_v2(
    p_request_id,p_member_id,p_booking_date,p_start_time,p_participants,p_member_note,
    p_contact_source,p_contact_surname,p_contact_salutation,p_contact_phone
  );
  perform public.replace_booking_benefit_selections_request(v_booking.id,p_member_id,p_benefits);
  return v_booking;
end;
$function$
CREATE OR REPLACE FUNCTION public.create_test_login_session_v2(p_token_hash text, p_member_id uuid, p_surface text, p_device_class text, p_expires_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_id uuid;
  v_now timestamptz := clock_timestamp();
begin
  if p_surface is null or p_surface <> all(array['member','points','event','calendar','booking']) then
    raise exception 'INVALID_TEST_SURFACE';
  end if;
  if p_device_class is null or p_device_class <> all(array['pc','mobile']) then
    raise exception 'INVALID_TEST_DEVICE_CLASS';
  end if;
  if p_expires_at <= v_now then
    raise exception 'INVALID_TEST_SESSION_EXPIRY';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_member_id::text || ':' || p_surface, 0));

  update public.test_login_sessions
     set revoked_at = v_now
   where member_id = p_member_id
     and surface = p_surface
     and revoked_at is null
     and expires_at <= v_now;

  if exists (
    select 1
      from public.member_presence_sessions ps
     where ps.member_id = p_member_id
       and ps.surface = p_surface
       and ps.offline_at is null
       and ps.last_seen_at >= v_now - interval '90 seconds'
  ) or exists (
    select 1
      from public.test_login_sessions s
     where s.member_id = p_member_id
       and s.surface = p_surface
       and s.revoked_at is null
       and s.expires_at > v_now
       and s.created_at >= v_now - interval '15 seconds'
  ) then
    raise exception 'TEST_SURFACE_ALREADY_ACTIVE';
  end if;

  update public.test_login_sessions
     set revoked_at = v_now
   where member_id = p_member_id
     and surface = p_surface
     and revoked_at is null
     and expires_at > v_now;

  insert into public.test_login_sessions(
    token_hash, member_id, device_class, surface, expires_at
  )
  values (
    p_token_hash, p_member_id, p_device_class, p_surface, p_expires_at
  )
  returning id into v_id;

  return v_id;
end
$function$
