CREATE OR REPLACE FUNCTION public.delete_point_card(p_actor_line_user_id text, p_card_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_card uuid;
  v_ticket_count integer := 0;
  v_entry_count integer := 0;
begin
  select id into v_card from public.point_cards where card_id=p_card_id for update;
  if not found then raise exception 'POINT_CARD_NOT_FOUND'; end if;

  select count(*)::integer into v_ticket_count from public.point_tickets where point_card_id=v_card;
  select count(*)::integer into v_entry_count from public.point_entries where point_card_id=v_card;

  delete from public.point_tickets where point_card_id=v_card;
  delete from public.point_entries where point_card_id=v_card;
  delete from public.point_balances where point_card_id=v_card;
  delete from public.point_card_rewards where point_card_id=v_card;
  delete from public.point_cards where id=v_card;

  insert into public.audit_logs(
    audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail
  ) values (
    public.new_public_id('AUD'),p_actor_line_user_id,'admin','admin.pointcards.delete',
    'point_card',p_card_id,'success',
    jsonb_build_object('deletedTicketCount',v_ticket_count,'deletedEntryCount',v_entry_count)
  );

  return jsonb_build_object(
    'cardId',p_card_id,
    'deletedTicketCount',v_ticket_count,
    'deletedEntryCount',v_entry_count
  );
end;
$function$
CREATE OR REPLACE FUNCTION public.dismiss_accessible_receipt_request(p_receipt_id text, p_expected_updated_at timestamp with time zone, p_actor text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r public.booking_receipts%rowtype;
begin
  perform 1 from public.admins where line_user_id=p_actor and role='admin' and status='active';
  if not found then raise exception 'ADMIN_REQUIRED'; end if;
  select * into r from public.booking_receipts where receipt_id=p_receipt_id;
  if not found then raise exception 'RECEIPT_NOT_FOUND'; end if;
  perform 1 from public.members where id=r.member_id for update;
  select * into r from public.booking_receipts where receipt_id=p_receipt_id for update;
  if r.status='failed' and r.failure_reason='admin-dismissed' then return true; end if;
  if r.submission_mode<>'accessible' or r.booking_id is not null or r.status<>'awaiting_review' then raise exception 'RECEIPT_NOT_PENDING'; end if;
  if p_expected_updated_at is null or r.updated_at<>p_expected_updated_at then raise exception 'BOOKING_CONFLICT'; end if;
  update public.booking_receipts set status='failed',failure_reason='admin-dismissed',updated_at=now() where id=r.id;
  insert into public.booking_receipt_cleanup_queue(object_path,reason) values(r.object_path,'admin-dismissed') on conflict(object_path) do nothing;
  insert into public.audit_logs(audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail)
  values(public.new_public_id('AUD'),p_actor,'admin','admin.booking.receipt.dismiss','receipt',p_receipt_id,'success','{}');
  return true;
end $function$
