CREATE OR REPLACE FUNCTION public.pick_lottery_prize(p_prizes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_roll numeric := random()*100;
  v_cursor numeric := 0;
  v_item jsonb;
  v_last jsonb := null;
begin
  if jsonb_typeof(p_prizes) <> 'array' or jsonb_array_length(p_prizes)=0 then
    return jsonb_build_object('prizeTitle','未設定獎項','prizeDescription','');
  end if;
  for v_item in select value from jsonb_array_elements(p_prizes)
  loop
    v_last := v_item;
    v_cursor := v_cursor + greatest(0,coalesce((v_item->>'winRate')::numeric,0));
    if v_roll < v_cursor then return v_item - 'winRate'; end if;
  end loop;
  return coalesce(v_last - 'winRate',jsonb_build_object('prizeTitle','未設定獎項','prizeDescription',''));
end;
