CREATE OR REPLACE FUNCTION public.prepare_accessible_receipt_request(p_member_id uuid, p_request_id text, p_object_path text, p_mime_type text, p_size_bytes integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v public.booking_receipts%rowtype;
begin
  perform 1 from public.members where id=p_member_id and status='active' and membership_status='active' for update;
  if not found then raise exception 'MEMBERSHIP_REQUIRED'; end if;
  if coalesce(p_request_id,'') !~ '^[A-Za-z0-9_-]{8,120}$' then raise exception 'INVALID_REQUEST_ID'; end if;
  if p_mime_type is null or p_mime_type not in ('image/jpeg','image/png','image/webp','image/heic','image/heif') then raise exception 'RECEIPT_INVALID_MIME'; end if;
  if p_size_bytes is null or p_size_bytes not between 1 and 5242880 then raise exception 'RECEIPT_FILE_TOO_LARGE'; end if;
  if p_object_path is null or p_object_path not like p_member_id::text||'/accessible/%' then raise exception 'RECEIPT_INVALID_PATH'; end if;
  select * into v from public.booking_receipts where member_id=p_member_id and request_id=p_request_id for update;
  if found then
    if v.submission_mode<>'accessible' or v.declared_mime_type<>p_mime_type or v.declared_size_bytes<>p_size_bytes then raise exception 'REQUEST_ID_CONFLICT'; end if;
    if v.status not in ('pending_upload','awaiting_review','bound') then raise exception 'RECEIPT_NOT_PENDING'; end if;
    return jsonb_build_object('receiptId',v.receipt_id,'objectPath',v.object_path,'status',v.status,'alreadyPrepared',true);
  end if;
  with replaced as (
    update public.booking_receipts set status='failed',failure_reason='upload-replaced',updated_at=now()
    where member_id=p_member_id and submission_mode='accessible' and booking_id is null and status='pending_upload'
    returning object_path
  ) insert into public.booking_receipt_cleanup_queue(object_path,reason)
    select object_path,'upload-replaced' from replaced on conflict(object_path) do nothing;
  insert into public.booking_receipts(receipt_id,member_id,request_id,object_path,declared_mime_type,declared_size_bytes,submission_mode)
  values(public.new_public_id('BR'),p_member_id,p_request_id,p_object_path,p_mime_type,p_size_bytes,'accessible') returning * into v;
  return jsonb_build_object('receiptId',v.receipt_id,'objectPath',v.object_path,'status',v.status);
end $function$
CREATE OR REPLACE FUNCTION public.prepare_booking_receipt_request(p_booking_id uuid, p_member_id uuid, p_request_id text, p_object_path text, p_mime_type text, p_size_bytes integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_booking public.bookings%rowtype;
  v_existing public.booking_receipts%rowtype;
  v_receipt public.booking_receipts%rowtype;
begin
  p_request_id:=btrim(coalesce(p_request_id,''));
  p_object_path:=btrim(coalesce(p_object_path,''));
  p_mime_type:=lower(btrim(coalesce(p_mime_type,'')));

  if p_request_id !~ '^[A-Za-z0-9_-]{8,120}$' then raise exception 'INVALID_REQUEST_ID'; end if;
  if p_mime_type not in ('image/jpeg','image/png','image/webp','image/heic','image/heif') then raise exception 'RECEIPT_INVALID_MIME'; end if;
  if p_size_bytes is null or p_size_bytes<1 or p_size_bytes>5242880 then raise exception 'RECEIPT_FILE_TOO_LARGE'; end if;
  if p_object_path not like p_member_id::text||'/'||p_booking_id::text||'/%' then raise exception 'RECEIPT_INVALID_PATH'; end if;

  select * into v_booking
  from public.bookings
  where id=p_booking_id
  for update;
  if not found then raise exception 'BOOKING_NOT_FOUND'; end if;
  if v_booking.member_id<>p_member_id then raise exception 'BOOKING_NOT_OWNED'; end if;
  if v_booking.status<>'confirmed' then raise exception 'INVALID_BOOKING_TRANSITION'; end if;
  if v_booking.cancellation_requested_at is not null and v_booking.cancellation_reviewed_at is null then
    raise exception 'BOOKING_CANCELLATION_PENDING';
  end if;

  select * into v_existing
  from public.booking_receipts
  where member_id=p_member_id and request_id=p_request_id
  for update;
  if found then
    if v_existing.booking_id<>p_booking_id
       or v_existing.declared_mime_type<>p_mime_type
       or v_existing.declared_size_bytes<>p_size_bytes then
      raise exception 'REQUEST_ID_CONFLICT';
    end if;
    if v_existing.status not in ('pending_upload','awaiting_review','bound') then
      raise exception 'RECEIPT_NOT_PENDING';
    end if;
    return jsonb_build_object(
      'receiptId',v_existing.receipt_id,
      'objectPath',v_existing.object_path,
      'status',v_existing.status,
      'alreadyPrepared',true,
      'replacedExisting',false
    );
  end if;

  select * into v_existing
  from public.booking_receipts
  where booking_id=p_booking_id and status='bound'
  for update;
  if found then raise exception 'BOOKING_ALREADY_COMPLETED_WITH_RECEIPT'; end if;

  -- Keep the submitted snapshot visible until its replacement validates.
  -- Each attempt gets a new row and object, so an old finalize/upload cannot
  -- act on the replacement. A booking lock serializes competing prepares.
  select * into v_existing
  from public.booking_receipts
  where booking_id=p_booking_id and status='pending_upload'
  for update;
  if found then
    update public.booking_receipts
    set status='failed',failure_reason='upload-replaced',updated_at=now()
    where id=v_existing.id;
    insert into public.booking_receipt_cleanup_queue(object_path,reason)
    values(v_existing.object_path,'upload-replaced')
    on conflict(object_path) do nothing;
  end if;

  insert into public.booking_receipts(
    receipt_id,booking_id,member_id,request_id,object_path,declared_mime_type,declared_size_bytes
  ) values(
    public.new_public_id('BR'),p_booking_id,p_member_id,p_request_id,p_object_path,p_mime_type,p_size_bytes
  )
  returning * into v_receipt;

  return jsonb_build_object(
    'receiptId',v_receipt.receipt_id,
    'objectPath',v_receipt.object_path,
    'status',v_receipt.status,
    'alreadyPrepared',false,
    'replacedExisting',false
  );
end;
$function$
CREATE OR REPLACE FUNCTION public.prepare_e2e_event_redemption_day(p_member_id uuid, p_fixture_tag text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_day_start timestamptz := ((now() at time zone 'Asia/Taipei')::date::timestamp at time zone 'Asia/Taipei'); v_moved integer;
begin
  if p_fixture_tag is null or p_fixture_tag !~ '^[A-F0-9]{16}$' then raise exception 'INVALID_QA_FIXTURE'; end if;
  perform 1 from public.members where id=p_member_id and is_test_account is true and status='active' and membership_status='active' for update;
  if not found then raise exception 'TEST_ACCOUNT_REQUIRED'; end if;
  if not exists(select 1 from public.event_tickets where created_by='qa-ui:'||p_member_id::text||':'||p_fixture_tag
    and event_ticket_id like 'QA-UI-EVT-%' and deleted_at is null) then raise exception 'QA_FIXTURE_NOT_OWNED'; end if;
  update public.event_ticket_claims c set used_at=v_day_start-interval '1 second',updated_at=now()
  from public.event_tickets e
  where c.event_ticket_id=e.id and c.member_id=p_member_id and c.status='used'
    and c.used_at >= v_day_start
    and c.used_at < v_day_start+interval '1 day'
    and e.event_ticket_id like 'QA-UI-EVT-%'
    and e.created_by ~ ('^qa-ui:'||p_member_id::text||':[A-F0-9]{16}$');
  get diagnostics v_moved=row_count;
  return jsonb_build_object('qaHistoryMoved',v_moved,'fixtureDate',(v_day_start at time zone 'Asia/Taipei')::date,'productionLimitUnchanged',true);
end;
$function$
CREATE OR REPLACE FUNCTION public.prevent_booking_on_active_holiday()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
