CREATE OR REPLACE FUNCTION public.review_booking_cancellation(p_booking_id uuid, p_expected_updated_at timestamp with time zone, p_actor text, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_booking public.bookings%rowtype;
  v_now timestamptz := now();
  v_source_status text;
begin
  if p_decision not in ('approved','rejected') then
    raise exception 'INVALID_CANCELLATION_DECISION';
  end if;

  select * into v_booking
  from public.bookings
  where id = p_booking_id
  for update;

  if not found then
    raise exception 'BOOKING_NOT_FOUND';
  end if;

  if p_expected_updated_at is null or v_booking.updated_at <> p_expected_updated_at then
    raise exception 'BOOKING_CONFLICT';
  end if;

  if v_booking.cancellation_requested_at is null
     or v_booking.cancellation_reviewed_at is not null then
    raise exception 'CANCELLATION_NOT_PENDING';
  end if;

  if v_booking.status not in ('pending','confirmed')
     or v_booking.status <> v_booking.cancellation_source_status then
    raise exception 'BOOKING_CONFLICT';
  end if;

  v_source_status := v_booking.cancellation_source_status;

  if p_decision = 'approved' then
    update public.bookings
    set status = 'cancelled',
        cancelled_by = p_actor,
        cancelled_at = v_now,
        cancellation_reviewed_at = v_now,
        cancellation_reviewed_by = p_actor,
        cancellation_decision = 'approved'
    where id = v_booking.id
      and status = v_booking.status
      and updated_at = v_booking.updated_at
    returning * into v_booking;
  else
    update public.bookings
    set cancellation_requested_at = null,
        cancellation_requested_by = null,
        cancellation_source_status = null,
        cancellation_reviewed_at = v_now,
        cancellation_reviewed_by = p_actor,
        cancellation_decision = 'rejected'
    where id = v_booking.id
      and status = v_booking.status
      and updated_at = v_booking.updated_at
    returning * into v_booking;
  end if;

  if not found then
    raise exception 'BOOKING_CONFLICT';
  end if;

  return jsonb_build_object(
    'bookingId', v_booking.id,
    'status', v_booking.status,
    'sourceStatus', v_source_status,
    'decision', p_decision,
    'updatedAt', v_booking.updated_at
  );
end;
$function$
CREATE OR REPLACE FUNCTION public.revoke_deleted_fixed_ticket_benefits()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_now timestamptz := coalesce(new.deleted_at, now());
  v_cancelled_claims integer := 0;
  v_archived_events integer := 0;
  v_cancelled_messages integer := 0;
  v_prefix text := 'FIXED-' || new.fixed_ticket_id || '-';
begin
  if old.deleted_at is not null or new.deleted_at is null then
    return new;
  end if;

  update public.event_ticket_claims as claim
  set status = 'cancelled',
      updated_at = v_now
  from public.event_tickets as ticket
  where claim.event_ticket_id = ticket.id
    and ticket.fixed_ticket_template_id = new.id
    and claim.status = 'claimed';
  get diagnostics v_cancelled_claims = row_count;

  update public.scheduled_grant_messages
  set status = 'cancelled',
      last_error = 'fixed_ticket_deleted',
      updated_at = v_now
  where created_by = 'fixed-ticket-automation'
    and status in ('pending', 'failed')
    and left(request_id, char_length(v_prefix)) = v_prefix;
  get diagnostics v_cancelled_messages = row_count;

  update public.event_tickets
  set status = 'archived',
      deleted_at = coalesce(deleted_at, v_now),
      updated_by = coalesce(nullif(new.updated_by, ''), 'fixed-ticket-automation'),
      updated_at = v_now
  where fixed_ticket_template_id = new.id
    and deleted_at is null;
  get diagnostics v_archived_events = row_count;

  insert into public.audit_logs(
    audit_id, actor_line_user_id, actor_role, action, target_type, target_id, result, detail
  ) values (
    public.new_public_id('AUD'),
    coalesce(nullif(new.updated_by, ''), 'system'),
    case when coalesce(new.updated_by, '') = 'fixed-ticket-automation' then 'system' else 'admin' end,
    'fixed_ticket.delete.revoke_benefits',
    'fixed_ticket_template',
    new.fixed_ticket_id,
    'success',
    jsonb_build_object(
      'cancelledClaims', v_cancelled_claims,
      'archivedEventTickets', v_archived_events,
      'cancelledMessages', v_cancelled_messages
    )
  );

  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.save_booking_service_type(p_type_id uuid, p_name text, p_reward_minutes_per_point integer DEFAULT NULL::integer, p_reward_point_card_id uuid DEFAULT NULL::uuid, p_actor text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_type_id uuid;
  v_old_name text;
  v_name text := btrim(coalesce(p_name, ''));
  v_actor text := coalesce(nullif(btrim(coalesce(p_actor, '')), ''), 'system');
  v_sort_order integer;
  v_card public.point_cards%rowtype;
begin
  if char_length(v_name) not between 1 and 80 then
    raise exception 'INVALID_SERVICE_TYPE_NAME';
  end if;

  if (p_reward_minutes_per_point is null) <> (p_reward_point_card_id is null) then
    raise exception 'INVALID_BOOKING_REWARD_RULE';
  end if;

  if p_reward_minutes_per_point is not null
     and (p_reward_minutes_per_point < 1 or p_reward_minutes_per_point > 10080) then
    raise exception 'INVALID_BOOKING_REWARD_MINUTES';
  end if;

  if p_reward_point_card_id is not null then
    select * into v_card
    from public.point_cards
    where id = p_reward_point_card_id
    for update;

    if not found
       or v_card.status <> 'active'
       or (v_card.expiry_mode <> 'unlimited'
           and (v_card.expires_on is null
                or v_card.expires_on < (clock_timestamp() at time zone 'Asia/Taipei')::date)) then
      raise exception 'BOOKING_REWARD_POINT_CARD_UNAVAILABLE';
    end if;
  end if;

  if p_type_id is null then
    if exists (
      select 1 from public.booking_service_types
      where lower(btrim(name)) = lower(v_name)
    ) then
      raise exception 'DUPLICATE_SERVICE_TYPE';
    end if;

    select coalesce(max(sort_order), -1) + 1
      into v_sort_order
    from public.booking_service_types;

    insert into public.booking_service_types(name, sort_order)
    values (v_name, least(1000, v_sort_order))
    returning id into v_type_id;
  else
    select name into v_old_name
    from public.booking_service_types
    where id = p_type_id
    for update;

    if not found then
      raise exception 'BOOKING_SERVICE_TYPE_NOT_FOUND';
    end if;

    if exists (
      select 1 from public.booking_service_types
      where id <> p_type_id
        and lower(btrim(name)) = lower(v_name)
    ) then
      raise exception 'DUPLICATE_SERVICE_TYPE';
    end if;

    update public.booking_service_types
    set name = v_name,
        updated_at = now()
    where id = p_type_id;

    if lower(btrim(v_old_name)) <> lower(v_name) then
      update public.booking_services
      set service_type = v_name,
          description = '__TYPE__:' || v_name
      where coalesce(counts_toward_membership, true) = true
        and lower(btrim(coalesce(service_type, ''))) = lower(btrim(v_old_name));

      update public.booking_items bi
      set service_type = v_name
      from public.bookings b
      where b.id = bi.booking_id
        and b.status in ('pending', 'confirmed')
        and lower(btrim(coalesce(bi.service_type, ''))) = lower(btrim(v_old_name));

      update public.booking_participant_items bpi
      set service_type = v_name
      from public.booking_participants bp
      join public.bookings b on b.id = bp.booking_id
      where bpi.participant_id = bp.id
        and b.status in ('pending', 'confirmed')
        and lower(btrim(coalesce(bpi.service_type, ''))) = lower(btrim(v_old_name));
    end if;

    v_type_id := p_type_id;
  end if;

  if p_reward_minutes_per_point is null then
    delete from public.booking_service_type_rewards
    where service_type_id = v_type_id;
  else
    insert into public.booking_service_type_rewards(
      service_type_id, point_card_id, minutes_per_point,
      created_by, updated_by, created_at, updated_at
    )
    values (
      v_type_id, p_reward_point_card_id, p_reward_minutes_per_point,
      v_actor, v_actor, now(), now()
    )
    on conflict (service_type_id) do update
    set point_card_id = excluded.point_card_id,
        minutes_per_point = excluded.minutes_per_point,
        updated_by = excluded.updated_by,
        updated_at = now();
  end if;

  return (
    select jsonb_build_object(
      'id', t.id,
      'name', t.name,
      'sortOrder', t.sort_order,
      'rewardMinutesPerPoint', r.minutes_per_point,
      'rewardPointCardId', r.point_card_id,
      'rewardPointCardTitle', c.title,
      'createdAt', t.created_at,
      'updatedAt', t.updated_at
    )
    from public.booking_service_types t
    left join public.booking_service_type_rewards r on r.service_type_id = t.id
    left join public.point_cards c on c.id = r.point_card_id
    where t.id = v_type_id
  );
end;
$function$
CREATE OR REPLACE FUNCTION public.save_booking_settings_with_service_types(p_work_start_time time without time zone, p_work_end_time time without time zone, p_min_advance_days integer, p_service_types text[], p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_actor text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_current_updated_at timestamptz;
begin
  select updated_at
    into v_current_updated_at
  from public.booking_settings
  where id = 1
  for update;

  if not found then
    raise exception 'BOOKING_SETTINGS_MISSING';
  end if;

  if p_expected_updated_at is not null
     and v_current_updated_at <> p_expected_updated_at then
    raise exception 'BOOKING_SETTINGS_CONFLICT';
