    raise exception 'INVALID_MAX_ADVANCE_DAYS';
  end if;
  if p_max_advance_days > 0 and p_max_advance_days < p_min_advance_days then
    raise exception 'INVALID_ADVANCE_WINDOW';
  end if;
  if char_length(v_notice) > 2000 then raise exception 'INVALID_BOOKING_NOTICE'; end if;
  if p_store_service_minutes is null or p_store_service_minutes < 1 or p_store_service_minutes > 720 then
    raise exception 'INVALID_STORE_SERVICE_MINUTES';
  end if;

  perform 1
  from public.booking_services
  where id = v_store_id and deleted_at is null
  for update;
  if not found then raise exception 'BOOKING_STORE_SERVICE_MISSING'; end if;

  update public.booking_settings
  set work_start_time = p_work_start_time,
      work_end_time = p_work_end_time,
      min_advance_days = p_min_advance_days,
      max_advance_days = p_max_advance_days,
      booking_notice = v_notice,
      updated_by = nullif(btrim(coalesce(p_actor, '')), '')
  where id = 1
  returning * into v_saved;

  update public.booking_services
  set duration_minutes = p_store_service_minutes,
      updated_at = now()
  where id = v_store_id
    and deleted_at is null;

  return v_saved;
end;
$function$
CREATE OR REPLACE FUNCTION public.save_booking_shared_settings_v3(p_work_start_time time without time zone, p_work_end_time time without time zone, p_slot_interval_minutes integer, p_min_advance_days integer, p_max_advance_days integer, p_booking_notice text, p_store_service_minutes integer, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_actor text DEFAULT NULL::text)
 RETURNS booking_settings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_before public.booking_settings%rowtype;
  v_after public.booking_settings%rowtype;
  v_notice text := coalesce(p_booking_notice,'');
  v_store constant uuid := '00000000-0000-4000-8000-000000000010'::uuid;
begin
  if not exists (select 1 from public.admins where line_user_id = p_actor and role = 'admin' and status = 'active') then
    raise exception 'ADMIN_REQUIRED';
  end if;
  select * into v_before from public.booking_settings where id = 1 for update;
  if not found then raise exception 'BOOKING_SETTINGS_MISSING'; end if;
  if p_expected_updated_at is not null and v_before.updated_at <> p_expected_updated_at then raise exception 'BOOKING_SETTINGS_CONFLICT'; end if;
  if p_work_start_time is null or p_work_end_time is null or p_work_start_time = p_work_end_time
     or extract(second from p_work_start_time) <> 0 or extract(second from p_work_end_time) <> 0
     or extract(minute from p_work_start_time)::integer % 5 <> 0 or extract(minute from p_work_end_time)::integer % 5 <> 0 then
    raise exception 'INVALID_WORK_HOURS';
  end if;
  if p_slot_interval_minutes is null or p_slot_interval_minutes not between 5 and 120 or p_slot_interval_minutes % 5 <> 0 then
    raise exception 'INVALID_SLOT_INTERVAL';
  end if;
  if p_min_advance_days is null or p_min_advance_days not between 0 and 365 then raise exception 'INVALID_ADVANCE_DAYS'; end if;
  if p_max_advance_days is null or p_max_advance_days not between 0 and 365 then raise exception 'INVALID_MAX_ADVANCE_DAYS'; end if;
  if p_max_advance_days > 0 and p_max_advance_days < p_min_advance_days then raise exception 'INVALID_ADVANCE_WINDOW'; end if;
  if char_length(v_notice) > 2000 then raise exception 'INVALID_BOOKING_NOTICE'; end if;
  if p_store_service_minutes is null or p_store_service_minutes not between 1 and 720 then raise exception 'INVALID_STORE_SERVICE_MINUTES'; end if;
  perform 1 from public.booking_services where id = v_store and deleted_at is null for update;
  if not found then raise exception 'BOOKING_STORE_SERVICE_MISSING'; end if;

  update public.booking_settings set work_start_time = p_work_start_time, work_end_time = p_work_end_time,
    slot_interval_minutes = p_slot_interval_minutes, min_advance_days = p_min_advance_days,
    max_advance_days = p_max_advance_days, booking_notice = v_notice,
    updated_by = nullif(btrim(coalesce(p_actor,'')),'') where id = 1 returning * into v_after;
  update public.booking_services set duration_minutes = p_store_service_minutes, updated_at = clock_timestamp()
    where id = v_store and deleted_at is null;

  insert into public.booking_audit_events(actor_line_user_id,actor_role,action,target_type,target_id,result,metadata)
    values (nullif(btrim(coalesce(p_actor,'')),''),'admin','BOOKING_SETTINGS_UPDATED','booking_settings','1','success',
      jsonb_build_object('before',jsonb_build_object('workStartTime',v_before.work_start_time,'workEndTime',v_before.work_end_time,
        'slotIntervalMinutes',v_before.slot_interval_minutes,'minAdvanceDays',v_before.min_advance_days,'maxAdvanceDays',v_before.max_advance_days),
        'after',jsonb_build_object('workStartTime',v_after.work_start_time,'workEndTime',v_after.work_end_time,
        'slotIntervalMinutes',v_after.slot_interval_minutes,'minAdvanceDays',v_after.min_advance_days,'maxAdvanceDays',v_after.max_advance_days)));
  return v_after;
end $function$
CREATE OR REPLACE FUNCTION public.save_booking_shared_settings_v4(p_work_start_time time without time zone, p_work_end_time time without time zone, p_slot_interval_minutes integer, p_min_advance_days integer, p_max_advance_days integer, p_booking_notice text, p_store_service_minutes integer, p_reminder_enabled boolean, p_reminder_time time without time zone, p_expected_updated_at timestamp with time zone, p_actor text)
 RETURNS booking_settings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_before public.booking_settings%rowtype;
        v_after public.booking_settings%rowtype;
begin
  if p_reminder_enabled is null or p_reminder_time is null
     or extract(second from p_reminder_time) <> 0 then
    raise exception 'INVALID_REMINDER_SETTINGS';
  end if;
  -- v3 locks the settings row, validates the actor and all existing settings,
  -- and records the existing settings audit in this same transaction.
  select * into v_before from public.booking_settings where id = 1;
  perform public.save_booking_shared_settings_v3(
    p_work_start_time, p_work_end_time, p_slot_interval_minutes,
    p_min_advance_days, p_max_advance_days, p_booking_notice,
    p_store_service_minutes, p_expected_updated_at, p_actor
  );
  update public.booking_settings
     set reminder_enabled = p_reminder_enabled, reminder_time = p_reminder_time,
         updated_by = p_actor
   where id = 1 returning * into v_after;
  insert into public.booking_audit_events
    (actor_line_user_id, actor_role, action, target_type, target_id, result, metadata)
  values (p_actor, 'admin', 'BOOKING_REMINDER_SETTINGS_UPDATED',
          'booking_settings', '1', 'success',
          jsonb_build_object('before', jsonb_build_object(
            'enabled', v_before.reminder_enabled, 'time', v_before.reminder_time),
            'after', jsonb_build_object(
            'enabled', v_after.reminder_enabled, 'time', v_after.reminder_time)));
  return v_after;
end $function$
CREATE OR REPLACE FUNCTION public.save_calendar_item_with_bonus(p_actor_line_user_id text, p_calendar_item jsonb, p_expected_updated_at text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_item jsonb := coalesce(p_calendar_item, '{}'::jsonb);
  v_type text := coalesce(v_item->>'itemType','');
  v_enabled boolean := coalesce((v_item->>'bonusPointsEnabled')::boolean,false);
  v_points integer := coalesce((v_item->>'bonusPoints')::integer,0);
  v_result jsonb;
  v_id text;
begin
  if v_type <> 'event' then
    v_enabled := false;
    v_points := 0;
  elsif v_enabled then
    if v_points < 1 or v_points > 100 then
      raise exception 'INVALID_EVENT_BONUS_POINTS';
    end if;
  else
    v_points := 0;
  end if;

  v_result := public.apply_calendar_batch(
    p_actor_line_user_id,
    jsonb_build_array(
      jsonb_build_object(
        'action','save',
        'calendarItem',v_item - 'bonusPointsEnabled' - 'bonusPoints',
        'expectedUpdatedAt',coalesce(p_expected_updated_at,'')
      )
    )
  );

  v_id := coalesce(v_result#>>'{0,calendarItemId}','');
  if v_id = '' then
    raise exception 'CALENDAR_ITEM_NOT_FOUND';
  end if;

  update public.calendar_items
  set bonus_points_enabled=v_enabled,
      bonus_points=v_points,
      updated_by=p_actor_line_user_id,
      updated_at=now()
  where calendar_item_id=v_id;

  return v_result;
end;
$function$
CREATE OR REPLACE FUNCTION public.save_membership_terms_draft(p_actor text, p_id uuid, p_version text, p_title text, p_summary text, p_body text, p_required boolean, p_effective_at timestamp with time zone, p_reconsent_existing boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_id uuid; v_before jsonb;
begin
 if not public.membership_terms_admin_ok(p_actor) then raise exception 'ADMIN_REQUIRED'; end if;
 if p_version is null or length(btrim(p_version)) not between 1 and 40
    or p_title is null or length(btrim(p_title)) not between 1 and 120
    or p_body is null or length(btrim(p_body)) not between 1 and 20000
    or length(coalesce(p_summary,'')) > 500 or p_effective_at is null then
   raise exception 'INVALID_TERMS';
 end if;
 if p_id is null then
   insert into public.membership_terms(version,title,summary,body,required,effective_at,reconsent_existing,created_by,updated_by)
   values(btrim(p_version),btrim(p_title),coalesce(p_summary,''),p_body,coalesce(p_required,true),p_effective_at,coalesce(p_reconsent_existing,false),p_actor,p_actor)
   returning id into v_id;
 else
   select to_jsonb(t) into v_before from public.membership_terms t where id=p_id and status='draft' for update;
   if v_before is null then raise exception 'TERMS_IMMUTABLE'; end if;
   update public.membership_terms set version=btrim(p_version),title=btrim(p_title),summary=coalesce(p_summary,''),
      body=p_body,required=coalesce(p_required,true),effective_at=p_effective_at,
      reconsent_existing=coalesce(p_reconsent_existing,false),updated_by=p_actor,updated_at=now()
    where id=p_id returning id into v_id;
 end if;
 insert into public.audit_logs(audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail)
 values('AUD-'||replace(gen_random_uuid()::text,'-',''),p_actor,'admin','MEMBERSHIP_TERMS_DRAFT_SAVE','membership_terms',v_id::text,'success',
        jsonb_build_object('before',v_before,'after',(select to_jsonb(t) from public.membership_terms t where id=v_id)));
 return v_id;
end $function$
CREATE OR REPLACE FUNCTION public.save_point_card(p_actor_line_user_id text, p_card jsonb, p_expected_updated_at timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_card_id text := nullif(trim(p_card->>'cardId'),'');
  v_id uuid;
  v_now timestamptz := now();
  v_reward jsonb;
  v_template_id uuid;
  v_threshold integer;
  v_reward_row_id uuid;
  v_matched_reward_ids uuid[] := array[]::uuid[];
  v_style_key text := lower(trim(coalesce(nullif(p_card->>'pointCardStyleKey',''), nullif(p_card->>'styleKey',''), '')));
  v_required_service_types text[] := '{}'::text[];
  v_requested_service_type_count integer := 0;
begin
  v_style_key := case v_style_key
    when 'forest' then 'lagoon'
    when 'midnight' then 'skyline'
    when 'ocean' then 'denim'
    when 'sunset' then 'coral'
    when 'lavender' then 'violet'
    when 'rose' then 'berry'
    when 'gold' then 'citrus'
    when 'platinum' then 'cocoa'
    when 'mint' then 'lime'
    when 'cherry' then 'peach'
    else v_style_key
  end;

  if v_style_key not in ('citrus','coral','lagoon','skyline','violet','berry','cocoa','lime','denim','peach') then
    raise exception 'INVALID_POINT_CARD_STYLE';
  end if;

  if v_card_id is null then
    v_card_id := public.new_public_id('PC');
    insert into public.point_cards(
      card_id,title,status,accent,style_key,expiry_mode,expires_on,sort_order,usage_method,usage_instructions,benefit_description,
      created_by,updated_by
    ) values(
      v_card_id,trim(p_card->>'title'),p_card->>'status',p_card->>'accent',v_style_key,p_card->>'expiryMode',
      nullif(p_card->>'expiresOn','')::date,coalesce((select max(sort_order)+1 from public.point_cards),0),
      coalesce(p_card->>'usageMethod',''),coalesce(p_card->>'usageInstructions',''),coalesce(p_card->>'benefitDescription',''),
      p_actor_line_user_id,p_actor_line_user_id
    ) returning id into v_id;
  else
    select id into v_id from public.point_cards where card_id=v_card_id for update;
    if not found then raise exception 'POINT_CARD_NOT_FOUND'; end if;
    if p_expected_updated_at is not null and not exists(select 1 from public.point_cards where id=v_id and updated_at=p_expected_updated_at) then
      raise exception 'CONFLICT';
    end if;
    update public.point_cards set
      title=trim(p_card->>'title'),status=p_card->>'status',accent=p_card->>'accent',style_key=v_style_key,
      expiry_mode=p_card->>'expiryMode',expires_on=nullif(p_card->>'expiresOn','')::date,
      usage_method=coalesce(p_card->>'usageMethod',''),usage_instructions=coalesce(p_card->>'usageInstructions',''),
      benefit_description=coalesce(p_card->>'benefitDescription',''),
      updated_by=p_actor_line_user_id,updated_at=v_now
    where id=v_id;
  end if;

  if jsonb_typeof(p_card->'rewards')='array' then
    for v_reward in select value from jsonb_array_elements(p_card->'rewards')
    loop
      begin
        v_threshold := (v_reward->>'thresholdStamps')::integer;
      exception when others then
        raise exception 'INVALID_REWARD_THRESHOLD';
      end;
      if v_threshold < 1 or v_threshold > 100 then raise exception 'INVALID_REWARD_THRESHOLD'; end if;

      select id into v_template_id
      from public.ticket_templates
      where ticket_template_id=v_reward->>'ticketTemplateId';
      if not found then raise exception 'TICKET_TEMPLATE_NOT_FOUND'; end if;

      v_required_service_types := '{}'::text[];
      v_requested_service_type_count := 0;
      if v_reward ? 'requiredServiceTypes' and v_reward->'requiredServiceTypes' is not null then
        if jsonb_typeof(v_reward->'requiredServiceTypes') <> 'array'
           or jsonb_array_length(v_reward->'requiredServiceTypes') > 20 then
          raise exception 'INVALID_REQUIRED_SERVICE_TYPES';
        end if;

        select count(distinct lower(btrim(value)))
          into v_requested_service_type_count
        from jsonb_array_elements_text(v_reward->'requiredServiceTypes')
        where btrim(value) <> '';

        select coalesce(array_agg(t.name order by t.sort_order, t.created_at), '{}'::text[])
          into v_required_service_types
        from public.booking_service_types t
        where exists (
          select 1
          from jsonb_array_elements_text(v_reward->'requiredServiceTypes') requested(value)
          where lower(btrim(requested.value)) = lower(btrim(t.name))
        );

        if cardinality(v_required_service_types) <> v_requested_service_type_count then
          raise exception 'INVALID_REQUIRED_SERVICE_TYPES';
        end if;
      end if;

      v_reward_row_id := null;
      select r.id into v_reward_row_id
      from public.point_card_rewards r
      where r.point_card_id=v_id and r.threshold_stamps=v_threshold and not (r.id = any(v_matched_reward_ids))
      limit 1 for update;

      if v_reward_row_id is null then
        select r.id into v_reward_row_id
        from public.point_card_rewards r
        where r.point_card_id=v_id and r.ticket_template_id=v_template_id and not (r.id = any(v_matched_reward_ids))
        order by r.threshold_stamps limit 1 for update;
      end if;

      if v_reward_row_id is null then
        insert into public.point_card_rewards(
          reward_id,point_card_id,threshold_stamps,ticket_template_id,required_service_types
        )
        values(
          public.new_public_id('RW'),v_id,v_threshold,v_template_id,v_required_service_types
        )
        returning id into v_reward_row_id;
      else
        update public.point_card_rewards
        set threshold_stamps=v_threshold,
            ticket_template_id=v_template_id,
            required_service_types=v_required_service_types,
            updated_at=v_now
        where id=v_reward_row_id;
      end if;
      v_matched_reward_ids := array_append(v_matched_reward_ids,v_reward_row_id);
    end loop;
  end if;

  if cardinality(v_matched_reward_ids)=0 then
    delete from public.point_card_rewards where point_card_id=v_id;
  else
    delete from public.point_card_rewards where point_card_id=v_id and not (id = any(v_matched_reward_ids));
  end if;

  insert into public.audit_logs(audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail)
  values(public.new_public_id('AUD'),p_actor_line_user_id,'admin','admin.pointcards.save','point_card',v_card_id,'success',
    jsonb_build_object(
      'stableRewardIdentity',true,
      'rewardCount',cardinality(v_matched_reward_ids),
      'styleKey',v_style_key,
      'bookingServiceRuleAtRewardNode',true
    ));
  return v_card_id;
end;
$function$
CREATE OR REPLACE FUNCTION public.save_point_card_service_items(p_actor_line_user_id text, p_card jsonb, p_expected_updated_at timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_card_id text;
  v_card_uuid uuid;
  v_reward jsonb;
  v_threshold integer;
  v_reward_id uuid;
  v_required_service_ids uuid[] := '{}'::uuid[];
  v_required_service_match_mode text := 'any';
  v_requested_count integer := 0;
begin
  v_card_id := public.save_point_card(p_actor_line_user_id, p_card, p_expected_updated_at);

  select id into v_card_uuid
  from public.point_cards
  where card_id = v_card_id;

  if v_card_uuid is null then
    raise exception 'POINT_CARD_NOT_FOUND';
  end if;

  if jsonb_typeof(p_card->'rewards') = 'array' then
    for v_reward in select value from jsonb_array_elements(p_card->'rewards')
    loop
      begin
        v_threshold := (v_reward->>'thresholdStamps')::integer;
      exception when others then
        raise exception 'INVALID_REWARD_THRESHOLD';
      end;

      v_required_service_ids := '{}'::uuid[];
      v_required_service_match_mode := case
        when lower(btrim(coalesce(v_reward->>'requiredServiceMatchMode', 'any'))) = 'all' then 'all'
        else 'any'
      end;
      v_requested_count := 0;

      if v_reward ? 'requiredServiceIds' and v_reward->'requiredServiceIds' is not null then
        if jsonb_typeof(v_reward->'requiredServiceIds') <> 'array'
           or jsonb_array_length(v_reward->'requiredServiceIds') > 20 then
          raise exception 'INVALID_REQUIRED_SERVICE_IDS';
        end if;

        select count(distinct btrim(value))
          into v_requested_count
        from jsonb_array_elements_text(v_reward->'requiredServiceIds')
        where btrim(value) <> '';

        select coalesce(array_agg(bs.id order by bs.created_at, bs.id), '{}'::uuid[])
          into v_required_service_ids
        from public.booking_services bs
        where bs.deleted_at is null
          and bs.id <> '00000000-0000-4000-8000-000000000010'::uuid
          and exists (
            select 1
            from jsonb_array_elements_text(v_reward->'requiredServiceIds') requested(value)
            where btrim(requested.value) = bs.id::text
          );

        if cardinality(v_required_service_ids) <> v_requested_count then
          raise exception 'INVALID_REQUIRED_SERVICE_IDS';
        end if;
      end if;

      select id into v_reward_id
      from public.point_card_rewards
      where point_card_id = v_card_uuid and threshold_stamps = v_threshold
      limit 1;

      if v_reward_id is null then
        raise exception 'INVALID_REWARD_THRESHOLD';
      end if;

      update public.point_card_rewards
      set required_service_ids = v_required_service_ids,
          required_service_match_mode = v_required_service_match_mode,
          updated_at = now()
      where id = v_reward_id;
    end loop;
  end if;

  return v_card_id;
end;
$function$
CREATE OR REPLACE FUNCTION public.save_tier_settings(p_actor_line_user_id text, p_settings jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_item jsonb;
  v_expected timestamptz;
  v_previous integer := -1;
  v_value integer;
  v_key text;
  v_style text;
  v_index integer := 0;
  v_expected_key text;
  v_label text;
begin
  if jsonb_typeof(p_settings) <> 'array' or jsonb_array_length(p_settings) <> 4 then
    raise exception 'INVALID_TIER_SETTINGS';
  end if;

  for v_item in select value from jsonb_array_elements(p_settings)
  loop
    v_index := v_index + 1;
    v_expected_key := (array['general','silver','gold','platinum'])[v_index];
    v_key := v_item->>'tierKey';
    v_style := v_item->>'styleKey';

    if v_key is distinct from v_expected_key then
      raise exception 'INVALID_TIER_SETTINGS';
    end if;

    v_value := (v_item->>'requiredServiceMinutes')::integer;
    if v_index = 1 then
      if v_value <> 0 then raise exception 'INVALID_TIER_SETTINGS'; end if;
    elsif v_value <= v_previous then
      raise exception 'INVALID_TIER_SETTINGS';
    end if;
    if v_value < 0 or v_value > 10000000 then
      raise exception 'INVALID_TIER_SETTINGS';
    end if;
    v_previous := v_value;

    if v_style not in ('forest','midnight','ocean','sunset','lavender','rose','gold','platinum','mint','cherry') then
      raise exception 'INVALID_TIER_SETTINGS';
    end if;

    v_expected := nullif(v_item->>'expectedUpdatedAt','')::timestamptz;
    if v_expected is not null and not exists(
      select 1
      from public.membership_tier_settings
      where tier_key = v_key and updated_at = v_expected
    ) then
      raise exception 'CONFLICT';
    end if;

    v_label := case v_key
      when 'general' then '一般會員'
      when 'silver' then '銀級會員'
      when 'gold' then '金級會員'
      when 'platinum' then '白金會員'
    end;

    insert into public.membership_tier_settings(
      tier_key, tier_label, required_service_minutes, style_key, updated_by, updated_at
    )
    values(
      v_key, v_label, v_value, v_style, p_actor_line_user_id, now()
    )
    on conflict (tier_key) do update set
      tier_label = excluded.tier_label,
      required_service_minutes = excluded.required_service_minutes,
      style_key = excluded.style_key,
      updated_by = excluded.updated_by,
      updated_at = excluded.updated_at;
  end loop;

  insert into public.audit_logs(
    audit_id, actor_line_user_id, actor_role, action, target_type, target_id, result
