CREATE OR REPLACE FUNCTION public.sync_fixed_ticket_calendar_item(p_template_id uuid, p_event_ticket_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_template public.fixed_ticket_templates%rowtype;
  v_event public.event_tickets%rowtype;
  v_calendar_title text;
  v_calendar_description text;
  v_calendar_status text;
  v_audience_type text;
  v_audience_month smallint;
begin
  select * into v_template
  from public.fixed_ticket_templates
  where id = p_template_id;

  select * into v_event
  from public.event_tickets
  where id = p_event_ticket_id;

  if v_template.id is null or v_event.id is null then
    return;
  end if;

  if v_template.deleted_at is not null
     or v_template.status <> 'active'
     or v_template.calendar_enabled is not true
     or v_event.deleted_at is not null then
    delete from public.calendar_items
    where source_event_ticket_id = p_event_ticket_id;
    return;
  end if;

  if v_event.starts_on is null then
    return;
  end if;

  if v_template.schedule_type = 'birthday_month' then
    v_calendar_title := v_event.title;
    v_calendar_description := coalesce(v_event.description, '');
    v_calendar_status := 'targeted';
    v_audience_type := 'birthday_month';
    v_audience_month := extract(month from v_event.starts_on)::smallint;
  else
    v_calendar_title := v_event.title;
    v_calendar_description := coalesce(v_event.description, '');
    v_calendar_status := 'active';
    v_audience_type := 'all';
    v_audience_month := null;
  end if;

  insert into public.calendar_items(
    calendar_item_id,
    title,
    item_type,
    description,
    starts_on,
    ends_on,
    status,
    accent,
    allowed_tier_keys,
    link_label,
    link_url,
    created_by,
    updated_by,
    source_event_ticket_id,
    audience_type,
    audience_month
  ) values (
    public.new_public_id('CAL'),
    v_calendar_title,
    'event',
    v_calendar_description,
    v_event.starts_on,
    v_event.ends_on,
    v_calendar_status,
    v_event.accent,
    v_event.allowed_tier_keys,
    '查看活動票券',
    'https://yongshengchen0615.github.io/MemberWebsocket-dev/event/?source=event-ticket-calendar&eventTicketId=' || v_event.event_ticket_id,
    'fixed-ticket-automation',
    'fixed-ticket-automation',
    v_event.id,
    v_audience_type,
    v_audience_month
  )
  on conflict (source_event_ticket_id)
    where source_event_ticket_id is not null
  do update set
    title = excluded.title,
    item_type = excluded.item_type,
    description = excluded.description,
    starts_on = excluded.starts_on,
    ends_on = excluded.ends_on,
    status = excluded.status,
    accent = excluded.accent,
    allowed_tier_keys = excluded.allowed_tier_keys,
    link_label = excluded.link_label,
    link_url = excluded.link_url,
    audience_type = excluded.audience_type,
    audience_month = excluded.audience_month,
    updated_by = 'fixed-ticket-automation',
    updated_at = now();
end;
$function$
