CREATE OR REPLACE FUNCTION public.transfer_member_points(p_sender_line_user_id text, p_receiver_member_code text, p_card_id text, p_amount integer, p_request_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_sender public.members%rowtype;
  v_receiver public.members%rowtype;
  v_card public.point_cards%rowtype;
  v_existing public.point_transfers%rowtype;
  v_sender_balance integer;
  v_receiver_balance integer;
  v_transfer_id text;
  v_today date := (clock_timestamp() at time zone 'Asia/Taipei')::date;
begin
  p_receiver_member_code:=btrim(coalesce(p_receiver_member_code,''));
  p_card_id:=btrim(coalesce(p_card_id,''));
  p_request_id:=btrim(coalesce(p_request_id,''));

  if p_request_id !~ '^[A-Za-z0-9_-]{8,120}$' then raise exception 'INVALID_REQUEST_ID'; end if;
  if p_amount is null or p_amount <= 0 then raise exception 'INVALID_TRANSFER_AMOUNT'; end if;
  if p_receiver_member_code='' then raise exception 'TRANSFER_RECEIVER_REQUIRED'; end if;
  if p_card_id='' then raise exception 'POINT_CARD_REQUIRED'; end if;

  select * into v_sender
  from public.members
  where line_user_id=p_sender_line_user_id
    and status='active'
    and membership_status='active';
  if not found then raise exception 'MEMBERSHIP_REQUIRED'; end if;

  select * into v_receiver
  from public.members
  where upper(member_code)=upper(p_receiver_member_code)
    and status='active'
    and membership_status='active';
  if not found then raise exception 'TRANSFER_RECEIVER_NOT_FOUND'; end if;
  if v_sender.id=v_receiver.id then raise exception 'TRANSFER_SELF_NOT_ALLOWED'; end if;

  perform 1
  from public.members
  where id in (v_sender.id,v_receiver.id)
  order by id
  for update;

  select * into v_card
  from public.point_cards
  where card_id=p_card_id
  for update;
  if not found then raise exception 'POINT_CARD_NOT_FOUND'; end if;
  if v_card.status<>'active' then raise exception 'POINT_CARD_NOT_AVAILABLE'; end if;
  if v_card.expiry_mode='date' and (v_card.expires_on is null or v_card.expires_on<v_today) then
    raise exception 'POINT_CARD_EXPIRED';
  end if;

  select * into v_existing
  from public.point_transfers
  where sender_member_id=v_sender.id
    and request_id=p_request_id
  for update;
  if found then
    if v_existing.receiver_member_id<>v_receiver.id
       or v_existing.point_card_id<>v_card.id
       or v_existing.amount<>p_amount then
      raise exception 'REQUEST_ID_CONFLICT';
    end if;
    select stamps into v_sender_balance from public.point_balances
      where member_id=v_sender.id and point_card_id=v_card.id;
    select stamps into v_receiver_balance from public.point_balances
      where member_id=v_receiver.id and point_card_id=v_card.id;
    return jsonb_build_object(
      'transferId',v_existing.transfer_id,
      'requestId',p_request_id,
      'cardId',v_card.card_id,
      'amount',v_existing.amount,
      'receiverMemberCode',v_receiver.member_code,
      'senderBalance',coalesce(v_sender_balance,0),
      'receiverBalance',coalesce(v_receiver_balance,0),
      'alreadyApplied',true
    );
  end if;

  insert into public.point_balances(member_id,point_card_id,stamps,updated_at)
  values(v_receiver.id,v_card.id,0,now())
  on conflict (member_id,point_card_id) do nothing;

  perform 1
  from public.point_balances
  where point_card_id=v_card.id
    and member_id in (v_sender.id,v_receiver.id)
  order by member_id
  for update;

  select stamps into v_sender_balance
  from public.point_balances
  where member_id=v_sender.id and point_card_id=v_card.id;
  if not found or v_sender_balance<p_amount then raise exception 'INSUFFICIENT_POINTS'; end if;

  update public.point_balances
  set stamps=stamps-p_amount,updated_at=now()
  where member_id=v_sender.id and point_card_id=v_card.id
  returning stamps into v_sender_balance;

  update public.point_balances
  set stamps=stamps+p_amount,updated_at=now()
  where member_id=v_receiver.id and point_card_id=v_card.id
  returning stamps into v_receiver_balance;

  v_transfer_id:=public.new_public_id('PT');
  insert into public.point_transfers(
    transfer_id,request_id,sender_member_id,receiver_member_id,point_card_id,amount
  ) values (
    v_transfer_id,p_request_id,v_sender.id,v_receiver.id,v_card.id,p_amount
  );

  insert into public.point_entries(
    entry_id,member_id,point_card_id,amount,note,created_by,request_id,entry_type,reference_type,reference_id
  ) values (
    public.new_public_id('PE'),v_sender.id,v_card.id,-p_amount,'會員點數轉贈',v_sender.line_user_id,
    p_request_id,'transfer_out','point_transfer',v_transfer_id
  );

  insert into public.point_entries(
    entry_id,member_id,point_card_id,amount,note,created_by,request_id,entry_type,reference_type,reference_id
  ) values (
    public.new_public_id('PE'),v_receiver.id,v_card.id,p_amount,'收到會員點數轉贈',v_sender.line_user_id,
    p_request_id,'transfer_in','point_transfer',v_transfer_id
  );

  perform public.issue_eligible_point_tickets(v_receiver.id,v_card.id);

  insert into public.audit_logs(
    audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail
  ) values (
    public.new_public_id('AUD'),v_sender.line_user_id,'member','user.pointcard.transfer',
    'point_transfer',v_transfer_id,'success',
    jsonb_build_object(
      'senderMemberId',v_sender.id,
      'receiverMemberId',v_receiver.id,
      'pointCardId',v_card.card_id,
      'amount',p_amount,
      'requestId',p_request_id
    )
  );

  insert into public.realtime_events(scope,event_type)
  values('points','point.transfer');

  return jsonb_build_object(
    'transferId',v_transfer_id,
    'requestId',p_request_id,
    'cardId',v_card.card_id,
    'amount',p_amount,
    'receiverMemberCode',v_receiver.member_code,
    'senderBalance',v_sender_balance,
    'receiverBalance',v_receiver_balance,
    'alreadyApplied',false
  );
end;
$function$
CREATE OR REPLACE FUNCTION public.update_booking_bundle_request(p_booking_id uuid, p_expected_updated_at timestamp with time zone, p_actor text, p_request_id text, p_member_id uuid, p_booking_date date, p_start_time time without time zone, p_items jsonb, p_member_note text DEFAULT ''::text)
 RETURNS bookings
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_settings public.booking_settings%rowtype;
  v_member public.members%rowtype;
  v_existing public.bookings%rowtype;
  v_booking public.bookings%rowtype;
  v_service public.booking_services%rowtype;
  v_item jsonb;
  v_service_id uuid;
  v_primary_service_id uuid;
  v_seen_service_ids uuid[] := array[]::uuid[];
  v_quantity integer;
  v_total_duration integer := 0;
  v_today date := (now() at time zone 'Asia/Taipei')::date;
  v_local_time time := (now() at time zone 'Asia/Taipei')::time;
  v_end_time time;
  v_item_count integer;
begin
  if p_request_id is null or char_length(btrim(p_request_id)) < 12 or char_length(p_request_id) > 100 then
    raise exception 'INVALID_REQUEST_ID';
  end if;

  select * into v_existing from public.bookings
  where id = p_booking_id and member_id = p_member_id for update;
  if not found then raise exception 'BOOKING_NOT_EDITABLE'; end if;
  if v_existing.request_id = p_request_id then return v_existing; end if;
  if p_expected_updated_at is null or v_existing.updated_at <> p_expected_updated_at then
    raise exception 'BOOKING_CONFLICT';
  end if;
  if v_existing.status not in ('pending', 'confirmed')
     or v_existing.booking_date + v_existing.start_time <= (clock_timestamp() at time zone 'Asia/Taipei') then
    raise exception 'BOOKING_NOT_EDITABLE';
  end if;
  select * into v_member
  from public.members
  where id = p_member_id;

  if not found then raise exception 'MEMBER_NOT_FOUND'; end if;
  if coalesce(v_member.membership_status, '') <> 'active' then raise exception 'MEMBERSHIP_REQUIRED'; end if;
  if coalesce(v_member.status, '') <> 'active' then raise exception 'MEMBER_DISABLED'; end if;

  select * into v_settings
  from public.booking_settings
  where id = 1
  for share;
  if not found then raise exception 'BOOKING_SETTINGS_MISSING'; end if;
  if v_settings.primary_technician_id is null
     or not exists (select 1 from public.booking_technicians where id = v_settings.primary_technician_id and is_active = true) then
    raise exception 'BOOKING_PRIMARY_TECHNICIAN_REQUIRED';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' then raise exception 'INVALID_BOOKING_ITEMS'; end if;
  v_item_count := jsonb_array_length(p_items);
  if v_item_count < 1 or v_item_count > 20 then raise exception 'INVALID_BOOKING_ITEMS'; end if;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    begin
      v_service_id := (v_item ->> 'serviceId')::uuid;
      v_quantity := coalesce((v_item ->> 'quantity')::integer, 1);
    exception when others then
      raise exception 'INVALID_BOOKING_ITEMS';
    end;

    if v_quantity < 1 or v_quantity > 2 then raise exception 'INVALID_BOOKING_QUANTITY'; end if;
    if v_service_id = any(v_seen_service_ids) then raise exception 'DUPLICATE_BOOKING_SERVICE'; end if;
    v_seen_service_ids := array_append(v_seen_service_ids, v_service_id);

    select * into v_service
    from public.booking_services
    where id = v_service_id
    for share;
    if not found then raise exception 'BOOKING_SERVICE_NOT_FOUND'; end if;
    if not v_service.is_active then raise exception 'BOOKING_SERVICE_DISABLED'; end if;

    if v_primary_service_id is null then v_primary_service_id := v_service_id; end if;
    v_total_duration := v_total_duration + (v_service.duration_minutes * v_quantity);
  end loop;

  if v_total_duration < 1 or v_total_duration > 1440 then raise exception 'INVALID_BOOKING_DURATION'; end if;
  if p_booking_date < public.booking_business_date(clock_timestamp() at time zone 'Asia/Taipei',v_settings.work_start_time,v_settings.work_end_time) + coalesce(v_settings.min_advance_days,0) then raise exception 'BOOKING_TOO_EARLY'; end if;
  if public.booking_slot_start_at(p_booking_date,p_start_time,v_settings.work_start_time,v_settings.work_end_time) <= (clock_timestamp() at time zone 'Asia/Taipei') then raise exception 'BOOKING_TIME_PASSED'; end if;
  if extract(second from p_start_time) <> 0 then raise exception 'INVALID_BOOKING_SLOT'; end if;

  v_end_time := p_start_time + make_interval(mins => v_total_duration);
  if not public.booking_slot_fits(p_booking_date,p_start_time,v_total_duration,v_settings.work_start_time,v_settings.work_end_time,v_settings.slot_interval_minutes) then
    raise exception 'INVALID_BOOKING_SLOT';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_booking_date::text, 0));

  begin
    update public.bookings set
      request_id = p_request_id, service_id = v_primary_service_id,
      technician_id = v_settings.primary_technician_id, booking_date = p_booking_date, start_time = p_start_time, end_time = v_end_time,
      total_duration_minutes = v_total_duration, status = 'pending',
      member_note = left(coalesce(p_member_note, ''), 500), admin_note = '',
      confirmed_by = null, confirmed_at = null
    where id = p_booking_id returning * into v_booking;
  exception
    when exclusion_violation or unique_violation then
      raise exception 'BOOKING_SLOT_TAKEN';
  end;

  delete from public.booking_items where booking_id = p_booking_id;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    v_service_id := (v_item ->> 'serviceId')::uuid;
    v_quantity := coalesce((v_item ->> 'quantity')::integer, 1);
    select * into v_service from public.booking_services where id = v_service_id;

    insert into public.booking_items(
      booking_id, service_id, service_title, unit_duration_minutes, quantity
    ) values (
      v_booking.id, v_service.id, v_service.title, v_service.duration_minutes, v_quantity
    );
  end loop;

  insert into public.booking_audit_events(actor_line_user_id, actor_role, action, target_type, target_id, result, metadata)
  values (p_actor, 'member', 'BOOKING_UPDATED', 'booking', p_booking_id::text, 'success',
    jsonb_build_object('previousDate', v_existing.booking_date, 'previousStartTime', v_existing.start_time,
      'previousStatus', v_existing.status, 'bookingDate', p_booking_date, 'startTime', p_start_time));
  return v_booking;
end;
$function$
