    '店內招待',
    '09:00:00',
    '17:00:00',
    30,
    0,
    array[0,1,2,3,4,5,6]::smallint[],
    10,
    0,
    false,
    true,
    false,
    'system'
  )
  on conflict (id) do nothing;

  insert into public.birthday_benefit_settings(
    singleton,
    enabled,
    updated_by
  )
  values (true, false, 'system')
  on conflict (singleton) do nothing;

  insert into public.test_mode_settings(
    id,
    enabled,
    allow_admin_user_login,
    maintenance_message,
    updated_by,
    maintenance_enabled,
    allow_pc_test_login,
    allow_mobile_test_login
  )
  values (true, false, false, '', 'system', false, false, false)
  on conflict (id) do nothing;

  insert into booking_notifications.config(id, enabled)
  values (true, true)
  on conflict (id) do update
    set enabled = excluded.enabled;

  -- Postconditions: a one-click clear must be atomic. If any required baseline
  -- cannot be rebuilt, raise so the surrounding TRUNCATE transaction rolls back
  -- instead of leaving a partially-cleared, unusable system.
  if not exists (
    select 1
      from public.booking_settings bs
      join public.booking_technicians t
        on t.id = bs.primary_technician_id
       and t.is_active = true
     where bs.id = 1
  ) then
    raise exception 'REQUIRED_BOOKING_BASELINE_INVALID';
  end if;

  if not exists (
    select 1
      from public.booking_service_types
     where lower(btrim(name)) = lower(btrim('店內招待'))
  ) then
    raise exception 'REQUIRED_BOOKING_SERVICE_TYPE_BASELINE_INVALID';
  end if;

  if not exists (
    select 1
      from public.booking_services
     where id = '00000000-0000-4000-8000-000000000010'::uuid
       and is_active = true
       and lower(btrim(coalesce(service_type, ''))) = lower(btrim('店內招待'))
  ) then
    raise exception 'REQUIRED_BOOKING_SERVICE_BASELINE_INVALID';
  end if;

  if (select count(*) from public.membership_tier_settings
      where tier_key in ('general','silver','gold','platinum')) < 4 then
    raise exception 'REQUIRED_MEMBERSHIP_TIER_BASELINE_INVALID';
  end if;

  if not exists (select 1 from public.point_card_settings where id = 1)
     or not exists (select 1 from public.birthday_benefit_settings where singleton = true)
     or not exists (select 1 from public.test_mode_settings where id = true)
     or not exists (select 1 from booking_notifications.config where id = true) then
    raise exception 'REQUIRED_SYSTEM_SETTINGS_BASELINE_INVALID';
  end if;
end;
$function$
CREATE OR REPLACE FUNCTION line_config.status()
 RETURNS TABLE(setting_key text, setting_type text, current_value text, configured boolean, source_name text, description text, updated_by text, updated_at timestamp with time zone)
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  select
    s.setting_key,
    s.setting_type,
    case
      when s.setting_type = 'secret'
        then case when vs.id is null then '[missing]' else '[configured]' end
      else s.value_text
    end as current_value,
    case
      when s.setting_type = 'secret' then vs.id is not null
      else nullif(btrim(s.value_text), '') is not null
    end as configured,
    coalesce(s.vault_secret_name, 'line_config.settings') as source_name,
    s.description,
    s.updated_by,
    s.updated_at
  from line_config.settings s
  left join vault.secrets vs
    on s.setting_type = 'secret'
   and vs.name = s.vault_secret_name
  order by s.setting_key;
$function$
CREATE OR REPLACE FUNCTION line_config.set_secret(p_key text, p_secret text, p_description text DEFAULT NULL::text)
 RETURNS TABLE(setting_key text, configured boolean, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_secret_name text;
  v_description text;
  v_secret_id uuid;
  v_updated_at timestamptz;
begin
  if p_key is null or btrim(p_key) = '' then
    raise exception 'LINE setting key is required';
  end if;

  if p_secret is null or length(btrim(p_secret)) < 10 then
    raise exception 'LINE secret/token must be at least 10 characters';
  end if;

  select s.vault_secret_name, s.description
    into v_secret_name, v_description
  from line_config.settings s
  where s.setting_key = p_key
    and s.setting_type = 'secret';

  if v_secret_name is null then
    raise exception 'Unknown or non-secret LINE setting key: %', p_key;
  end if;

  select s.id
    into v_secret_id
  from vault.secrets s
  where s.name = v_secret_name
  order by s.updated_at desc
  limit 1;

  if v_secret_id is null then
    perform vault.create_secret(
      p_secret,
      v_secret_name,
      coalesce(nullif(btrim(p_description), ''), v_description),
      null::uuid
    );
  else
    perform vault.update_secret(
      v_secret_id,
      p_secret,
      v_secret_name,
      coalesce(nullif(btrim(p_description), ''), v_description),
      null::uuid
    );
  end if;

  update line_config.settings s
  set updated_by = current_user,
      updated_at = now(),
      description = coalesce(nullif(btrim(p_description), ''), s.description)
  where s.setting_key = p_key
  returning s.updated_at into v_updated_at;

  insert into line_config.audit_log(action, setting_key, actor, detail)
  values (
    'secret_updated',
    p_key,
    current_user,
    jsonb_build_object('vault_secret_name', v_secret_name)
  );

  return query
  select p_key, true, v_updated_at;
end;
$function$
CREATE OR REPLACE FUNCTION line_config.set_value(p_key text, p_value text)
 RETURNS TABLE(setting_key text, value_text text, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_type text;
  v_old_value text;
  v_new_value text := nullif(btrim(p_value), '');
  v_updated_at timestamptz;
begin
  select s.setting_type, s.value_text
    into v_type, v_old_value
  from line_config.settings s
  where s.setting_key = p_key
    and s.setting_type <> 'secret';

  if v_type is null then
    raise exception 'Unknown or secret LINE setting key: %', p_key;
  end if;

  if v_new_value is null then
    raise exception 'LINE setting value cannot be empty';
  end if;

  if v_type = 'url' and v_new_value !~ '^https://[^[:space:]]+$' then
    raise exception 'LINE URL setting must be a valid HTTPS URL';
  end if;

  if v_type = 'boolean' and lower(v_new_value) not in ('true','false') then
    raise exception 'LINE boolean setting must be true or false';
  end if;

  update line_config.settings s
  set value_text = case when v_type = 'boolean' then lower(v_new_value) else v_new_value end,
      updated_by = current_user,
      updated_at = now()
  where s.setting_key = p_key
  returning s.value_text, s.updated_at
    into v_new_value, v_updated_at;

  insert into line_config.audit_log(action, setting_key, actor, detail)
  values (
    'value_updated',
    p_key,
    current_user,
    jsonb_build_object('old_value', v_old_value, 'new_value', v_new_value)
  );

  return query
  select p_key, v_new_value, v_updated_at;
end;
$function$
